INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u5-C1','math',2,1,'u5',2,'같은 것끼리 모아 정리하기 — 흩어진 물건을 같은 것끼리 모으면 찾기 쉽고 깔끔해짐을 알고, 정리가 분류의 시작임을 알기',ARRAY['2수04-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u5-C2','math',2,1,'u5',2,'분명한 기준 알기 — 색깔·모양·종류·다리 수처럼 누가 나누어도 결과가 같은 기준과, 좋아하는·예쁜·맛있는처럼 사람마다 다른 기준을 구별하기',ARRAY['2수04-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u5-C3','math',2,1,'u5',3,'기준에 따라 분류하기 — 물건의 특징을 살펴 정한 기준에 맞는 칸에 한 번씩만 넣고, 같은 물건도 기준이 다르면 분류 결과가 달라짐을 알기',ARRAY['2수04-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u5-C4','math',2,1,'u5',4,'분류하고 세기 — 기준에 따라 나눈 뒤 ／ 표시를 하며 빠짐없이 세어 표로 나타내고, 각 칸의 수를 더하면 전체 수가 됨을 알기',ARRAY['2수04-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u5-C5','math',2,1,'u5',5,'분류한 결과 말하기 — 분류하여 센 결과에서 가장 많은 것·가장 적은 것·몇 개 더 많은지·전체 수를 말하고, 결과로 알 수 있는 것과 쓰임을 찾기',ARRAY['2수04-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X01','math',2,'u5',ARRAY['M2-1-u5-C1']::text[],'정리는 같은 것끼리 모으는 것임을 몰라 물건을 섞어 담거나 빈자리에 아무렇게나 둔다','「이것과 같은 것은 어디 있지?」 하고 같은 것끼리 한곳에 모으기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X02','math',2,'u5',ARRAY['M2-1-u5-C2','M2-1-u5-C3']::text[],'좋아하는·예쁜·맛있는·멋진처럼 사람마다 다른 기준을 분명한 기준으로 여긴다','「친구가 나누어도 똑같이 나올까?」 물어보기 — 다르게 나오면 분명한 기준이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X03','math',2,'u5',ARRAY['M2-1-u5-C3']::text[],'칸을 겹치거나 빠뜨리게 나눈다 — 한 물건을 두 칸에 넣거나 어느 칸에도 넣지 않고, 몇 가지로 나뉘는지 잘못 센다','한 가지 기준으로 칸을 정하고, 물건마다 들어갈 칸이 꼭 하나인지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X04','math',2,'u5',ARRAY['M2-1-u5-C2','M2-1-u5-C3']::text[],'기준은 한 가지뿐이라고 여기거나, 기준을 바꾸어도 분류 결과가 같다고 여긴다','같은 단추를 색깔로 한 번, 모양으로 한 번 나누어 두 결과를 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X05','math',2,'u5',ARRAY['M2-1-u5-C3','M2-1-u5-C4']::text[],'물건의 특징(색깔·모양·다리 수·바퀴 수·움직이는 곳)을 잘못 보거나 다른 특징에 끌려 엉뚱한 칸에 넣거나 엉뚱한 칸을 센다','기준 하나만 손가락으로 짚고, 그 특징만 보며 하나씩 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X06','math',2,'u5',ARRAY['M2-1-u5-C4']::text[],'표시 없이 세어 빠뜨리거나 같은 것을 두 번 센다','하나 셀 때마다 ／ 표시를 하고, 다 센 뒤 표시 수와 물건 수를 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X07','math',2,'u5',ARRAY['M2-1-u5-C4','M2-1-u5-C5']::text[],'전체 수가 각 칸 수의 합임을 몰라 한 칸의 수를 전체로 말하거나, 합계를 한 칸의 수로 쓴다','각 칸의 수를 모두 더하면 전체 — 합계에서 아는 칸을 빼면 모르는 칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X08','math',2,'u5',ARRAY['M2-1-u5-C4','M2-1-u5-C5']::text[],'몇 가지(칸의 수)와 몇 개(물건의 수)를 헷갈린다','「몇 가지」는 칸이 몇 개인지, 「몇 개」는 물건이 몇 개인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X09','math',2,'u5',ARRAY['M2-1-u5-C5']::text[],'분류한 결과로 알 수 없는 것(누가·언제·왜)까지 알 수 있다고 여긴다','표에는 칸 이름과 수만 있어요 — 표에 없는 것은 알 수 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X10','math',2,'u5',ARRAY['M2-1-u5-C5']::text[],'많고 적음을 수가 아니라 표의 자리(첫 칸)·그림 크기·이름으로 판단한다','칸 아래의 수끼리 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X11','math',2,'u5',ARRAY['M2-1-u5-C5']::text[],'「몇 개 더 많은지」를 두 수의 합이나 한쪽 수로 답한다','더 많은 수에서 더 적은 수를 빼기 — 하나씩 짝지어 남는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X12','math',2,'u5',ARRAY['M2-1-u5-C1','M2-1-u5-C2','M2-1-u5-C3','M2-1-u5-C4','M2-1-u5-C5']::text[],'묻는 말을 거꾸로 읽는다 — 가장 많은↔가장 적은, 잘못된↔바른, 아닌 것↔맞는 것','물음의 「적은·잘못된·아닌」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u5-X13','math',2,'u5',ARRAY['M2-1-u5-C4']::text[],'／ 표시의 다섯 개 묶음을 잘못 센다 — 묶음 하나를 4나 1로 셈','／ 다섯 개가 한 묶음 — 묶음은 5, 5, … 로 세고 남은 것을 이어 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_basic#1','math',2,1,'u5','L02','g2_1_math_u5_L02_basic','lesson_basic','M2-1-u5-C1',1,'mc','auto','어질러진 방을 정리할 때 가장 먼저 할 일은 무엇일까요?',ARRAY['M2-1-u5-X01']::text[],true,'{"seq":1,"concept":"M2-1-u5-C1","difficulty":1,"kind":"mc","stem":"어질러진 방을 정리할 때 가장 먼저 할 일은 무엇일까요?","options":[{"t":"같은 것끼리 모아요","correct":true},{"t":"아무 데나 빈 곳에 넣어요","mis":"M2-1-u5-X01"},{"t":"마음에 드는 것만 꺼내 놓아요","mis":"M2-1-u5-X01"}],"explanation":["물건이 흩어져 있으면 찾기 힘들어요.","옷은 옷끼리, 책은 책끼리 같은 것끼리 모아요.","같은 것끼리 모으면 깔끔하게 정리돼요."],"variant_rule":{"alt":[{"stem":"뒤섞인 책상 서랍을 정리하려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"연필은 연필끼리, 지우개는 지우개끼리 모아요","correct":true},{"t":"보이는 대로 한 칸에 모두 넣어요","mis":"M2-1-u5-X01"},{"t":"빈칸이 있는 곳에 아무렇게나 넣어요","mis":"M2-1-u5-X01"}],"explanation":["같은 것끼리 모아야 정리가 돼요.","연필은 연필 칸, 지우개는 지우개 칸에 넣어요.","그러면 찾을 때 바로 알 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_basic#2','math',2,1,'u5','L02','g2_1_math_u5_L02_basic','lesson_basic','M2-1-u5-C1',1,'mc','auto','같은 종류끼리 잘 모인 바구니는 어느 것인가요?',ARRAY['M2-1-u5-X01']::text[],true,'{"seq":2,"concept":"M2-1-u5-C1","difficulty":1,"kind":"mc","stem":"같은 종류끼리 잘 모인 바구니는 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M2-1-u5-X01"},{"t":"다","mis":"M2-1-u5-X01"}],"explanation":["가 바구니에는 과일만 모여 있어요.","나와 다 바구니에는 과일·학용품·동물이 섞여 있어요.","같은 것끼리 모아야 정리된 것이에요."],"asset":{"type":"sort_bins","bins":[{"label":"가","items":["🍎","🍌","🍇"]},{"label":"나","items":["✏️","🍎","🐶"]},{"label":"다","items":["👕","📓","🚗"]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 종류끼리 잘 모인 바구니는 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M2-1-u5-X01"},{"t":"다","mis":"M2-1-u5-X01"}],"explanation":["나 바구니에는 옷만 모여 있어요.","가와 다 바구니에는 여러 가지가 섞여 있어요.","같은 것끼리 모아야 정리된 것이에요."],"asset":{"type":"sort_bins","bins":[{"label":"가","items":["🐶","✏️","🚗"]},{"label":"나","items":["👕","👖","🧥"]},{"label":"다","items":["🍎","📏","🐱"]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_basic#3','math',2,1,'u5','L02','g2_1_math_u5_L02_basic','lesson_basic','M2-1-u5-C1',1,'ox','auto','같은 것끼리 모아 정리하면 필요한 물건을 쉽게 찾을 수 있어요.',ARRAY['M2-1-u5-X01']::text[],true,'{"seq":3,"concept":"M2-1-u5-C1","difficulty":1,"kind":"ox","stem":"같은 것끼리 모아 정리하면 필요한 물건을 쉽게 찾을 수 있어요.","answer":"O","reason_options":[{"t":"어디에 있는지 바로 알 수 있으니까","correct":true},{"t":"물건이 더 많아지니까","mis":"M2-1-u5-X01"}],"mis":"M2-1-u5-X01","explanation":["같은 것끼리 모이면 있을 곳이 정해져요.","그래서 찾기 쉽고 꺼내고 넣기도 쉬워요.","정리해도 물건 수는 그대로예요."],"variant_rule":{"alt":[{"stem":"물건을 정리하면 물건의 수가 늘어나요.","answer":"X","reason_options":[{"t":"자리만 바뀌고 물건의 수는 그대로니까","correct":true},{"t":"모아 두면 더 많아 보이니까","mis":"M2-1-u5-X01"}],"explanation":["정리는 물건을 같은 것끼리 모으는 일이에요.","물건의 수는 바뀌지 않아요.","찾기 쉬워지고 깔끔해져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_basic#4','math',2,1,'u5','L02','g2_1_math_u5_L02_basic','lesson_basic','M2-1-u5-C2',1,'mc','auto','옷을 나눌 때 누가 나누어도 결과가 같은 기준은 어느 것인가요?',ARRAY['M2-1-u5-X02']::text[],true,'{"seq":4,"concept":"M2-1-u5-C2","difficulty":1,"kind":"mc","stem":"옷을 나눌 때 누가 나누어도 결과가 같은 기준은 어느 것인가요?","options":[{"t":"윗옷과 아래옷","correct":true},{"t":"좋아하는 옷과 싫어하는 옷","mis":"M2-1-u5-X02"},{"t":"예쁜 옷과 안 예쁜 옷","mis":"M2-1-u5-X02"}],"explanation":["윗옷인지 아래옷인지는 누가 보아도 같아요.","좋아하는 옷, 예쁜 옷은 사람마다 달라요.","누가 나누어도 같은 기준이 분명한 기준이에요."],"variant_rule":{"alt":[{"stem":"자전거를 나눌 때 누가 나누어도 결과가 같은 기준은 어느 것인가요?","options":[{"t":"바퀴의 수","correct":true},{"t":"멋진 자전거와 멋지지 않은 자전거","mis":"M2-1-u5-X02"},{"t":"빨라 보이는 자전거와 느려 보이는 자전거","mis":"M2-1-u5-X02"}],"explanation":["바퀴가 몇 개인지는 누가 세어도 같아요.","멋진 것, 빨라 보이는 것은 사람마다 달라요.","그래서 바퀴의 수가 분명한 기준이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_basic#5','math',2,1,'u5','L02','g2_1_math_u5_L02_basic','lesson_basic','M2-1-u5-C2',2,'mc','auto','과일을 나누는 기준 가운데 분명한 기준이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u5-X12']::text[],true,'{"seq":5,"concept":"M2-1-u5-C2","difficulty":2,"kind":"mc","stem":"과일을 나누는 기준 가운데 분명한 기준이 아닌 것은 어느 것인가요?","options":[{"t":"맛있는 과일과 맛없는 과일","correct":true},{"t":"과일의 종류","mis":"M2-1-u5-X12"},{"t":"과일의 색깔","mis":"M2-1-u5-X12"}],"explanation":["맛있는지는 사람마다 생각이 달라요.","종류와 색깔은 누가 보아도 같아요.","「아닌 것」을 묻는지 다시 읽어요."],"variant_rule":{"alt":[{"stem":"동물을 나누는 기준 가운데 분명한 기준이 아닌 것은 어느 것인가요?","options":[{"t":"귀여운 동물과 안 귀여운 동물","correct":true},{"t":"다리의 수","mis":"M2-1-u5-X12"},{"t":"날개가 있는 것과 없는 것","mis":"M2-1-u5-X12"}],"explanation":["귀여운지는 사람마다 생각이 달라요.","다리의 수, 날개가 있는지는 누가 보아도 같아요.","「아닌 것」을 묻는지 다시 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_basic#6','math',2,1,'u5','L02','g2_1_math_u5_L02_basic','lesson_basic','M2-1-u5-C2',2,'ox','auto','「좋아하는 장난감과 싫어하는 장난감」은 분명한 기준이에요.',ARRAY['M2-1-u5-X02']::text[],true,'{"seq":6,"concept":"M2-1-u5-C2","difficulty":2,"kind":"ox","stem":"「좋아하는 장난감과 싫어하는 장난감」은 분명한 기준이에요.","answer":"X","reason_options":[{"t":"사람마다 좋아하는 것이 달라 결과가 달라지니까","correct":true},{"t":"내가 좋아하는지는 내가 잘 아니까","mis":"M2-1-u5-X02"}],"mis":"M2-1-u5-X02","explanation":["친구마다 좋아하는 장난감이 달라요.","그래서 나눈 결과가 사람마다 달라져요.","인형·자동차·블록처럼 종류로 나누면 분명해요."],"variant_rule":{"alt":[{"stem":"「색깔」은 누가 나누어도 결과가 같은 분명한 기준이에요.","answer":"O","reason_options":[{"t":"누가 보아도 빨간색은 빨간색이니까","correct":true},{"t":"사람마다 좋아하는 색이 다르니까","mis":"M2-1-u5-X02"}],"explanation":["색깔은 눈으로 보고 똑같이 알 수 있어요.","좋아하는 색은 달라도 물건의 색은 같아요.","그래서 색깔은 분명한 기준이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_basic#7','math',2,1,'u5','L02','g2_1_math_u5_L02_basic','lesson_basic','M2-1-u5-C2',2,'match','auto','물건과 그 물건을 나누기 알맞은 분명한 기준을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-1-u5-C2","difficulty":2,"kind":"match","stem":"물건과 그 물건을 나누기 알맞은 분명한 기준을 이으세요.","pairs":[{"l":"동물","r":"다리의 수"},{"l":"탈것","r":"움직이는 곳(땅·하늘·물)"},{"l":"옷","r":"윗옷과 아래옷"}],"mis":"M2-1-u5-X05","explanation":["동물은 다리가 몇 개인지로 나눌 수 있어요.","탈것은 땅·하늘·물 가운데 어디에서 움직이는지로 나눌 수 있어요.","옷은 윗옷과 아래옷으로 나눌 수 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 물건과 그 물건을 나누기 알맞은 분명한 기준을 이으세요.","pairs":[{"l":"단추","r":"색깔"},{"l":"학용품","r":"종류(연필·자·공책)"},{"l":"자전거와 자동차","r":"바퀴의 수"}],"explanation":["단추는 빨강·파랑처럼 색깔로 나눌 수 있어요.","학용품은 연필·자·공책처럼 종류로 나눌 수 있어요.","자전거와 자동차는 바퀴의 수로 나눌 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_basic#8','math',2,1,'u5','L02','g2_1_math_u5_L02_basic','lesson_basic','M2-1-u5-C2',2,'mc','auto','그림의 단추를 누가 나누어도 결과가 같게 나누려고 해요. 알맞은 기준은 어느 것인가요?',ARRAY['M2-1-u5-X02']::text[],true,'{"seq":8,"concept":"M2-1-u5-C2","difficulty":2,"kind":"mc","stem":"그림의 단추를 누가 나누어도 결과가 같게 나누려고 해요. 알맞은 기준은 어느 것인가요?","options":[{"t":"색깔","correct":true},{"t":"예쁜 단추와 안 예쁜 단추","mis":"M2-1-u5-X02"},{"t":"마음에 드는 단추와 아닌 단추","mis":"M2-1-u5-X02"}],"explanation":["색깔은 누가 보아도 같아요.","예쁜지, 마음에 드는지는 사람마다 달라요.","그래서 색깔로 나누어야 결과가 같아요."],"asset":{"type":"sort_pile","items":["🔴","🟦","💛","🟥","🔵","🟨","❤️","💙"]},"variant_rule":{"alt":[{"stem":"그림의 탈것을 누가 나누어도 결과가 같게 나누려고 해요. 알맞은 기준은 어느 것인가요?","options":[{"t":"움직이는 곳","correct":true},{"t":"멋진 것과 멋지지 않은 것","mis":"M2-1-u5-X02"},{"t":"타 보고 싶은 것과 아닌 것","mis":"M2-1-u5-X02"}],"explanation":["땅·하늘·물 가운데 어디에서 움직이는지는 누가 보아도 같아요.","멋진지, 타 보고 싶은지는 사람마다 달라요.","그래서 움직이는 곳으로 나누어야 결과가 같아요."],"asset":{"type":"sort_pile","items":["🚗","✈️","⛵","🚌","🚁","🚢","🚲"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_basic#9','math',2,1,'u5','L02','g2_1_math_u5_L02_basic','lesson_basic','M2-1-u5-C2',2,'mc','auto','같은 단추를 색깔로도 나누고 모양으로도 나눌 수 있어요. 이것으로 알 수 있는 것은 어느 것인가요?',ARRAY['M2-1-u5-X04','M2-1-u5-X03']::text[],true,'{"seq":9,"concept":"M2-1-u5-C2","difficulty":2,"kind":"mc","stem":"같은 단추를 색깔로도 나누고 모양으로도 나눌 수 있어요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"기준이 다르면 분류한 결과도 달라져요","correct":true},{"t":"분류는 한 가지 기준으로만 할 수 있어요","mis":"M2-1-u5-X04"},{"t":"나누면 언제나 두 묶음이 돼요","mis":"M2-1-u5-X03"}],"explanation":["같은 단추도 색깔로 나누면 색깔끼리, 모양으로 나누면 모양끼리 모여요.","기준을 바꾸면 나뉘는 모습이 달라져요.","기준은 여러 가지가 될 수 있어요."],"variant_rule":{"alt":[{"stem":"같은 책을 색깔로도 나누고 종류(동화책·과학책)로도 나눌 수 있어요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"한 물건을 여러 가지 기준으로 나눌 수 있어요","correct":true},{"t":"책은 색깔로만 나눌 수 있어요","mis":"M2-1-u5-X04"},{"t":"기준을 바꾸어도 나눈 결과는 똑같아요","mis":"M2-1-u5-X04"}],"explanation":["같은 책도 색깔로 나눌 수 있고 종류로도 나눌 수 있어요.","기준을 바꾸면 나뉘는 모습이 달라져요.","무엇을 알고 싶은지에 따라 기준을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_basic#10','math',2,1,'u5','L02','g2_1_math_u5_L02_basic','lesson_basic','M2-1-u5-C2',3,'error','auto','친구들이 과일을 나누는 기준을 말했어요. 분명하지 않은 기준을 말한 친구는 누구인가요?',ARRAY['M2-1-u5-X02','M2-1-u5-X12']::text[],true,'{"seq":10,"concept":"M2-1-u5-C2","difficulty":3,"kind":"error","stem":"친구들이 과일을 나누는 기준을 말했어요. 분명하지 않은 기준을 말한 친구는 누구인가요?","options":[{"t":"하람 — 「맛있는 과일과 맛없는 과일로 나눌래.」","correct":true,"mis_target":"M2-1-u5-X02"},{"t":"서윤 — 「과일의 색깔로 나눌래.」","mis":"M2-1-u5-X12"},{"t":"준우 — 「사과·귤·포도처럼 종류로 나눌래.」","mis":"M2-1-u5-X12"}],"explanation":["맛있는지는 사람마다 달라서 결과가 달라져요.","하람이의 기준이 분명하지 않아요.","색깔과 종류는 누가 나누어도 같아요."],"variant_rule":{"alt":[{"stem":"친구들이 동물을 나누는 기준을 말했어요. 분명하지 않은 기준을 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「무서운 동물과 안 무서운 동물로 나눌래.」","correct":true,"mis_target":"M2-1-u5-X02"},{"t":"은솔 — 「다리의 수로 나눌래.」","mis":"M2-1-u5-X12"},{"t":"지호 — 「날개가 있는 것과 없는 것으로 나눌래.」","mis":"M2-1-u5-X12"}],"explanation":["무서운지는 사람마다 달라요.","도윤이의 기준이 분명하지 않아요.","다리의 수와 날개는 누가 보아도 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_challenge#1','math',2,1,'u5','L02','g2_1_math_u5_L02_challenge','lesson_challenge','M2-1-u5-C2',2,'mc','auto','분명한 기준끼리만 짝지은 것은 어느 것인가요?',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":1,"concept":"M2-1-u5-C2","difficulty":2,"kind":"mc","stem":"분명한 기준끼리만 짝지은 것은 어느 것인가요?","options":[{"t":"색깔, 모양","correct":true},{"t":"색깔, 예쁜 것","mis":"M2-1-u5-X02"},{"t":"좋아하는 것, 모양","mis":"M2-1-u5-X02"}],"explanation":["색깔과 모양은 누가 보아도 같아요.","예쁜 것, 좋아하는 것은 사람마다 달라요.","두 기준이 모두 분명해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_challenge#2','math',2,1,'u5','L02','g2_1_math_u5_L02_challenge','lesson_challenge','M2-1-u5-C1',2,'ox','auto','정리함에 「연필」, 「지우개」처럼 이름표를 붙이면 물건을 넣을 곳을 바로 알 수 있어요.',ARRAY['M2-1-u5-X01']::text[],false,'{"seq":2,"concept":"M2-1-u5-C1","difficulty":2,"kind":"ox","stem":"정리함에 「연필」, 「지우개」처럼 이름표를 붙이면 물건을 넣을 곳을 바로 알 수 있어요.","answer":"O","reason_options":[{"t":"같은 것끼리 넣을 자리가 정해지니까","correct":true},{"t":"이름표는 꾸미는 것일 뿐이니까","mis":"M2-1-u5-X01"}],"mis":"M2-1-u5-X01","explanation":["이름표는 그 칸에 무엇을 모으는지 알려 줘요.","같은 것끼리 넣을 자리가 정해져요.","꺼낼 때도 바로 찾을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_challenge#3','math',2,1,'u5','L02','g2_1_math_u5_L02_challenge','lesson_challenge','M2-1-u5-C2',3,'mc','auto','세미와 슬기가 같은 옷 8벌을 나누었어요. 세미는 「윗옷과 아래옷」, 슬기는 「좋아하는 옷과 아닌 옷」으로 나누었어요. 다른 친구가 같은 기준으로 다시 나누어도 결과가 똑같이 나오는 사람은 누구인가요?',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":3,"concept":"M2-1-u5-C2","difficulty":3,"kind":"mc","stem":"세미와 슬기가 같은 옷 8벌을 나누었어요. 세미는 「윗옷과 아래옷」, 슬기는 「좋아하는 옷과 아닌 옷」으로 나누었어요. 다른 친구가 같은 기준으로 다시 나누어도 결과가 똑같이 나오는 사람은 누구인가요?","options":[{"t":"세미","correct":true},{"t":"슬기","mis":"M2-1-u5-X02"},{"t":"두 사람 모두","mis":"M2-1-u5-X02"}],"explanation":["윗옷인지 아래옷인지는 누가 보아도 같아요.","좋아하는 옷은 사람마다 달라요.","그래서 세미의 기준만 결과가 똑같이 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_challenge#4','math',2,1,'u5','L02','g2_1_math_u5_L02_challenge','lesson_challenge','M2-1-u5-C2',3,'error','auto','친구들이 교실의 공을 나누는 기준을 말했어요. 분명하지 않은 기준을 말한 친구는 누구인가요?',ARRAY['M2-1-u5-X02','M2-1-u5-X12']::text[],false,'{"seq":4,"concept":"M2-1-u5-C2","difficulty":3,"kind":"error","stem":"친구들이 교실의 공을 나누는 기준을 말했어요. 분명하지 않은 기준을 말한 친구는 누구인가요?","options":[{"t":"아린 — 「잘 튀어 보이는 공과 아닌 공으로 나눌래.」","correct":true,"mis_target":"M2-1-u5-X02"},{"t":"지안 — 「공의 색깔로 나눌래.」","mis":"M2-1-u5-X12"},{"t":"태민 — 「축구공·농구공·야구공처럼 종류로 나눌래.」","mis":"M2-1-u5-X12"}],"explanation":["잘 튀어 보이는지는 사람마다 다르게 볼 수 있어요.","아린이의 기준이 분명하지 않아요.","색깔과 종류는 누가 보아도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_challenge#5','math',2,1,'u5','L02','g2_1_math_u5_L02_challenge','lesson_challenge','M2-1-u5-C2',3,'mc','auto','「맛있는 과일과 맛없는 과일」 대신 쓸 수 있는 분명한 기준은 어느 것인가요?',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":5,"concept":"M2-1-u5-C2","difficulty":3,"kind":"mc","stem":"「맛있는 과일과 맛없는 과일」 대신 쓸 수 있는 분명한 기준은 어느 것인가요?","options":[{"t":"과일의 색깔","correct":true},{"t":"내가 좋아하는 과일","mis":"M2-1-u5-X02"},{"t":"먹고 싶은 과일","mis":"M2-1-u5-X02"}],"explanation":["맛있는지는 사람마다 달라요.","과일의 색깔은 누가 보아도 같아요.","좋아하는 것, 먹고 싶은 것도 사람마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_challenge#6','math',2,1,'u5','L02','g2_1_math_u5_L02_challenge','lesson_challenge','M2-1-u5-C1',3,'mc','auto','학급 문고의 책이 뒤섞여 있어요. 찾기 쉽게 정리하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u5-X02','M2-1-u5-X01']::text[],false,'{"seq":6,"concept":"M2-1-u5-C1","difficulty":3,"kind":"mc","stem":"학급 문고의 책이 뒤섞여 있어요. 찾기 쉽게 정리하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"동화책·과학책·위인전처럼 종류끼리 꽂아요","correct":true},{"t":"읽고 싶은 순서대로 꽂아요","mis":"M2-1-u5-X02"},{"t":"빈칸이 보이는 대로 아무 칸에나 꽂아요","mis":"M2-1-u5-X01"}],"explanation":["종류끼리 모으면 누구나 같은 자리에서 찾을 수 있어요.","읽고 싶은 순서는 사람마다 달라요.","아무 칸에나 꽂으면 다시 찾기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_challenge#7','math',2,1,'u5','L02','g2_1_math_u5_L02_challenge','lesson_challenge','M2-1-u5-C2',3,'mc','auto','그림의 과일을 누가 나누어도 결과가 같게 나누려면 어떤 기준이 좋을까요?',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":7,"concept":"M2-1-u5-C2","difficulty":3,"kind":"mc","stem":"그림의 과일을 누가 나누어도 결과가 같게 나누려면 어떤 기준이 좋을까요?","options":[{"t":"과일의 종류","correct":true},{"t":"맛있어 보이는 것과 아닌 것","mis":"M2-1-u5-X02"},{"t":"먹고 싶은 것과 아닌 것","mis":"M2-1-u5-X02"}],"explanation":["사과·바나나·포도처럼 종류는 누가 보아도 같아요.","맛있어 보이는 것, 먹고 싶은 것은 사람마다 달라요.","그래서 종류로 나누어요."],"asset":{"type":"sort_pile","items":["🍎","🍌","🍇","🍎","🍊","🍌","🍓"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_challenge#8','math',2,1,'u5','L02','g2_1_math_u5_L02_challenge','lesson_challenge','M2-1-u5-C2',4,'mc','auto','분명한 기준끼리만 짝지은 것은 어느 것인가요?',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":8,"concept":"M2-1-u5-C2","difficulty":4,"kind":"mc","stem":"분명한 기준끼리만 짝지은 것은 어느 것인가요?","options":[{"t":"다리의 수 — 날개가 있는지 없는지","correct":true},{"t":"다리의 수 — 귀여운지 아닌지","mis":"M2-1-u5-X02"},{"t":"무서운지 아닌지 — 날개가 있는지 없는지","mis":"M2-1-u5-X02"}],"explanation":["다리의 수와 날개가 있는지는 누가 보아도 같아요.","귀여운지, 무서운지는 사람마다 달라요.","짝지은 두 기준이 모두 분명한지 하나씩 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_challenge#9','math',2,1,'u5','L02','g2_1_math_u5_L02_challenge','lesson_challenge','M2-1-u5-C2',4,'essay','teacher','친구가 「장난감을 좋아하는 것과 싫어하는 것으로 나누자.」라고 했어요. 이 기준의 문제점을 쓰고, 누가 나누어도 결과가 같은 기준으로 고쳐 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u5-C2","difficulty":4,"kind":"essay","stem":"친구가 「장난감을 좋아하는 것과 싫어하는 것으로 나누자.」라고 했어요. 이 기준의 문제점을 쓰고, 누가 나누어도 결과가 같은 기준으로 고쳐 써 보세요.","answer_guide":{"answer":"예: 좋아하는 장난감은 사람마다 달라서 누가 나누느냐에 따라 결과가 달라진다. 인형·자동차·블록처럼 장난감의 종류로 나누면 누가 나누어도 같다.","scoring_points":["사람마다 생각이 달라 결과가 달라진다고 썼는가","종류·색깔·모양처럼 분명한 기준을 하나 골랐는가","고친 기준으로 나눈 칸의 예를 들었는가"]},"explanation":["좋아하는 것은 사람마다 달라요.","종류·색깔·모양은 누가 보아도 같아요.","분명한 기준으로 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L02_challenge#10','math',2,1,'u5','L02','g2_1_math_u5_L02_challenge','lesson_challenge','M2-1-u5-C1',4,'essay','teacher','같은 것끼리 모아 정리하면 좋은 점을 두 가지 쓰고, 내 방이나 교실에서 정리할 물건 하나를 골라 어떻게 모을지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u5-C1","difficulty":4,"kind":"essay","stem":"같은 것끼리 모아 정리하면 좋은 점을 두 가지 쓰고, 내 방이나 교실에서 정리할 물건 하나를 골라 어떻게 모을지 써 보세요.","answer_guide":{"answer":"예: 찾고 싶은 물건을 바로 찾을 수 있고, 꺼내고 넣기 쉽다. 필통 속 물건을 연필은 연필끼리, 색연필은 색연필끼리 모은다.","scoring_points":["좋은 점 두 가지(찾기 쉬움·깔끔함·꺼내고 넣기 쉬움·잃어버리지 않음 등)를 썼는가","정리할 물건을 골랐는가","같은 것끼리 모으는 방법을 썼는가"]},"explanation":["정리하면 찾기 쉽고 깔끔해요.","같은 것끼리 한곳에 모아요.","정리는 분류의 시작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_basic#1','math',2,1,'u5','L03','g2_1_math_u5_L03_basic','lesson_basic','M2-1-u5-C3',1,'mc','auto','동물을 다리 수에 따라 나누려고 해요. 🐔 닭이 들어갈 칸은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],true,'{"seq":1,"concept":"M2-1-u5-C3","difficulty":1,"kind":"mc","stem":"동물을 다리 수에 따라 나누려고 해요. 🐔 닭이 들어갈 칸은 어느 것인가요?","options":[{"t":"다리 2개","correct":true},{"t":"다리 4개","mis":"M2-1-u5-X05"},{"t":"다리 0개","mis":"M2-1-u5-X05"}],"explanation":["닭은 다리가 2개예요.","그래서 「다리 2개」 칸에 넣어요.","기준(다리 수)만 보고 칸을 골라요."],"variant_rule":{"alt":[{"stem":"동물을 다리 수에 따라 나누려고 해요. 🐟 물고기가 들어갈 칸은 어느 것인가요?","options":[{"t":"다리 0개","correct":true},{"t":"다리 2개","mis":"M2-1-u5-X05"},{"t":"다리 4개","mis":"M2-1-u5-X05"}],"explanation":["물고기는 다리가 없어요.","그래서 「다리 0개」 칸에 넣어요.","기준(다리 수)만 보고 칸을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_basic#2','math',2,1,'u5','L03','g2_1_math_u5_L03_basic','lesson_basic','M2-1-u5-C3',1,'mc','auto','탈것을 움직이는 곳에 따라 나누려고 해요. ⛵ 돛단배가 들어갈 칸은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],true,'{"seq":2,"concept":"M2-1-u5-C3","difficulty":1,"kind":"mc","stem":"탈것을 움직이는 곳에 따라 나누려고 해요. ⛵ 돛단배가 들어갈 칸은 어느 것인가요?","options":[{"t":"물","correct":true},{"t":"땅","mis":"M2-1-u5-X05"},{"t":"하늘","mis":"M2-1-u5-X05"}],"explanation":["돛단배는 물 위에서 움직여요.","그래서 「물」 칸에 넣어요.","움직이는 곳만 보고 칸을 골라요."],"variant_rule":{"alt":[{"stem":"탈것을 움직이는 곳에 따라 나누려고 해요. 🚁 헬리콥터가 들어갈 칸은 어느 것인가요?","options":[{"t":"하늘","correct":true},{"t":"땅","mis":"M2-1-u5-X05"},{"t":"물","mis":"M2-1-u5-X05"}],"explanation":["헬리콥터는 하늘을 날아요.","그래서 「하늘」 칸에 넣어요.","움직이는 곳만 보고 칸을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_basic#3','math',2,1,'u5','L03','g2_1_math_u5_L03_basic','lesson_basic','M2-1-u5-C3',1,'ox','auto','기준에 따라 분류할 때 한 물건은 한 칸에만 넣어요.',ARRAY['M2-1-u5-X03']::text[],true,'{"seq":3,"concept":"M2-1-u5-C3","difficulty":1,"kind":"ox","stem":"기준에 따라 분류할 때 한 물건은 한 칸에만 넣어요.","answer":"O","reason_options":[{"t":"두 칸에 넣으면 같은 것을 두 번 세게 되니까","correct":true},{"t":"마음에 드는 칸에 넣으면 되니까","mis":"M2-1-u5-X03"}],"mis":"M2-1-u5-X03","explanation":["한 기준으로 나누면 물건마다 들어갈 칸이 하나예요.","두 칸에 넣으면 셀 때 헷갈려요.","알맞은 칸 하나에 넣어요."],"variant_rule":{"alt":[{"stem":"기준에 따라 분류할 때 한 물건을 두 칸에 넣어도 괜찮아요.","answer":"X","reason_options":[{"t":"한 기준으로 나누면 들어갈 칸이 하나뿐이니까","correct":true},{"t":"많이 넣을수록 좋으니까","mis":"M2-1-u5-X03"}],"explanation":["한 물건은 한 칸에만 들어가요.","두 칸에 넣으면 같은 것을 두 번 세게 돼요.","알맞은 칸 하나를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_basic#4','math',2,1,'u5','L03','g2_1_math_u5_L03_basic','lesson_basic','M2-1-u5-C3',1,'mc','auto','그림의 과일을 종류에 따라 분류하면 몇 가지로 나눌 수 있을까요?',ARRAY['M2-1-u5-X08','M2-1-u5-X03']::text[],true,'{"seq":4,"concept":"M2-1-u5-C3","difficulty":1,"kind":"mc","stem":"그림의 과일을 종류에 따라 분류하면 몇 가지로 나눌 수 있을까요?","explanation":["종류를 살펴보면 사과, 바나나, 포도가 있어요.","그래서 3가지로 나눌 수 있어요.","물건의 수(8개)가 아니라 칸이 몇 가지인지 세어요."],"variant_rule":{"cls":{"ask":"groups","fams":["fruit","sup","recy"],"crits":["kind"],"k":3}},"options":[{"t":"3가지","correct":true},{"t":"8가지","mis":"M2-1-u5-X08"},{"t":"4가지","mis":"M2-1-u5-X03"}],"asset":{"type":"sort_pile","items":["🍌","🍇","🍇","🍎","🍎","🍎","🍌","🍇"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_basic#5','math',2,1,'u5','L03','g2_1_math_u5_L03_basic','lesson_basic','M2-1-u5-C3',2,'mc','auto','다리 수에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],true,'{"seq":5,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"다리 수에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?","explanation":["소는 다리가 4개인 동물이에요.","그래서 「다리 4개」 칸에 있어야 하는데 「다리 2개」 칸에 들어가 있어요.","칸의 이름과 물건의 특징을 하나씩 맞춰 봐요."],"variant_rule":{"cls":{"ask":"odd","fams":["ani","cloth"],"crits":["legs","part"]}},"options":[{"t":"🐮 소","correct":true},{"t":"🐬 돌고래","mis":"M2-1-u5-X05"},{"t":"🐶 강아지","mis":"M2-1-u5-X05"}],"asset":{"type":"sort_bins","crit":"legs","bins":[{"label":"다리 2개","items":["🐧","🦆","🦆","🐮"]},{"label":"다리 4개","items":["🐶","🐷"]},{"label":"다리 0개","items":["🐍","🐬"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_basic#6','math',2,1,'u5','L03','g2_1_math_u5_L03_basic','lesson_basic','M2-1-u5-C3',2,'mc','auto','블록을 색깔에 따라 나누었어요. 이 블록을 다시 나눌 수 있을까요? 맞는 말은 어느 것인가요?',ARRAY['M2-1-u5-X04']::text[],true,'{"seq":6,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"블록을 색깔에 따라 나누었어요. 이 블록을 다시 나눌 수 있을까요? 맞는 말은 어느 것인가요?","options":[{"t":"모양에 따라 다시 나눌 수 있어요","correct":true},{"t":"한 번 나누면 다시 나눌 수 없어요","mis":"M2-1-u5-X04"},{"t":"블록은 색깔로만 나누어야 해요","mis":"M2-1-u5-X04"}],"explanation":["같은 블록도 다른 기준으로 다시 나눌 수 있어요.","모양으로 나누면 색깔로 나눈 것과 다르게 나뉘어요.","기준은 여러 가지예요."],"variant_rule":{"alt":[{"stem":"동물을 다리 수에 따라 나누었어요. 이 동물을 다시 나눌 수 있을까요? 맞는 말은 어느 것인가요?","options":[{"t":"날개가 있는지에 따라 다시 나눌 수 있어요","correct":true},{"t":"한 번 나누면 다시 나눌 수 없어요","mis":"M2-1-u5-X04"},{"t":"동물은 다리 수로만 나누어야 해요","mis":"M2-1-u5-X04"}],"explanation":["같은 동물도 다른 기준으로 다시 나눌 수 있어요.","날개가 있는지로 나누면 다르게 나뉘어요.","기준은 여러 가지예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_basic#7','math',2,1,'u5','L03','g2_1_math_u5_L03_basic','lesson_basic','M2-1-u5-C3',2,'mc','auto','단추를 색깔에 따라 나누려고 해요. 🟦 파란 네모와 같은 칸에 들어갈 단추는 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],true,'{"seq":7,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"단추를 색깔에 따라 나누려고 해요. 🟦 파란 네모와 같은 칸에 들어갈 단추는 어느 것인가요?","options":[{"t":"🔵 파란 동그라미","correct":true},{"t":"🟥 빨간 네모","mis":"M2-1-u5-X05"},{"t":"🟨 노란 네모","mis":"M2-1-u5-X05"}],"explanation":["기준은 색깔이에요.","파란 네모는 파란색이니 같은 파란색인 파란 동그라미와 한 칸이에요.","모양이 같아도 색깔이 다르면 다른 칸이에요."],"variant_rule":{"alt":[{"stem":"단추를 모양에 따라 나누려고 해요. 🔴 빨간 동그라미와 같은 칸에 들어갈 단추는 어느 것인가요?","options":[{"t":"🟢 초록 동그라미","correct":true},{"t":"🟥 빨간 네모","mis":"M2-1-u5-X05"},{"t":"❤️ 빨간 하트","mis":"M2-1-u5-X05"}],"explanation":["기준은 모양이에요.","빨간 동그라미는 동그라미이니 같은 동그라미인 초록 동그라미와 한 칸이에요.","색깔이 같아도 모양이 다르면 다른 칸이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_basic#8','math',2,1,'u5','L03','g2_1_math_u5_L03_basic','lesson_basic','M2-1-u5-C3',2,'match','auto','기준과 그 기준으로 나눈 칸의 이름을 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-1-u5-C3","difficulty":2,"kind":"match","stem":"기준과 그 기준으로 나눈 칸의 이름을 이으세요.","pairs":[{"l":"색깔","r":"빨간색 · 파란색 · 노란색"},{"l":"모양","r":"동그라미 · 네모 · 하트"},{"l":"다리 수","r":"다리 0개 · 다리 2개 · 다리 4개"}],"mis":"M2-1-u5-X05","explanation":["색깔로 나누면 색깔 이름이 칸이 돼요.","모양으로 나누면 모양 이름이 칸이 돼요.","다리 수로 나누면 다리가 몇 개인지가 칸이 돼요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 기준과 그 기준으로 나눈 칸의 이름을 이으세요.","pairs":[{"l":"움직이는 곳","r":"땅 · 하늘 · 물"},{"l":"바퀴 수","r":"바퀴 2개 · 바퀴 4개"},{"l":"윗옷과 아래옷","r":"윗옷 · 아래옷"}],"explanation":["움직이는 곳으로 나누면 땅·하늘·물이 칸이 돼요.","바퀴 수로 나누면 바퀴가 몇 개인지가 칸이 돼요.","옷은 윗옷과 아래옷 두 칸이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_basic#9','math',2,1,'u5','L03','g2_1_math_u5_L03_basic','lesson_basic','M2-1-u5-C3',2,'mc','auto','종류에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],true,'{"seq":9,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"종류에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?","explanation":["종이 상자는 종이예요.","그래서 「종이」 칸에 있어야 하는데 「캔」 칸에 들어가 있어요.","칸의 이름과 물건의 특징을 하나씩 맞춰 봐요."],"variant_rule":{"cls":{"ask":"odd","fams":["recy","tok","veh"],"crits":["kind","color","where"]}},"options":[{"t":"📦 종이 상자","correct":true},{"t":"🥫 캔","mis":"M2-1-u5-X05"},{"t":"🧴 플라스틱 통","mis":"M2-1-u5-X05"}],"asset":{"type":"sort_bins","crit":"kind","bins":[{"label":"캔","items":["🥫","🥫","📦"]},{"label":"플라스틱","items":["🧴","🥤","🧴"]},{"label":"종이","items":["📰","📰"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_basic#10','math',2,1,'u5','L03','g2_1_math_u5_L03_basic','lesson_basic','M2-1-u5-C3',3,'mc','auto','물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?',ARRAY['M2-1-u5-X05','M2-1-u5-X02']::text[],true,'{"seq":10,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?","explanation":["칸마다 색깔이 같아요: 가 빨간색, 나 파란색, 다 노란색.","모양은 한 칸 안에서도 서로 달라요.","칸 안의 물건이 모두 같은 특징을 찾으면 그것이 기준이에요."],"variant_rule":{"cls":{"ask":"crit","fams":["tok","veh"],"crits":["color","shape","where"]}},"options":[{"t":"색깔","correct":true},{"t":"모양","mis":"M2-1-u5-X05"},{"t":"예쁜 것과 안 예쁜 것","mis":"M2-1-u5-X02"}],"asset":{"type":"sort_bins","bins":[{"label":"가","items":["🔴","🔴","❤️"]},{"label":"나","items":["🔵","🟦","💙"]},{"label":"다","items":["🟡","🟨","🟡"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_challenge#1','math',2,1,'u5','L03','g2_1_math_u5_L03_challenge','lesson_challenge','M2-1-u5-C3',2,'mc','auto','움직이는 곳에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],true,'{"seq":1,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"움직이는 곳에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?","explanation":["자동차는 땅에서 움직이는 탈것이에요.","그래서 「땅」 칸에 있어야 하는데 「하늘」 칸에 들어가 있어요.","칸의 이름과 물건의 특징을 하나씩 맞춰 봐요."],"variant_rule":{"cls":{"ask":"odd","fams":["veh","ani"],"crits":["where","legs"]}},"options":[{"t":"🚗 자동차","correct":true},{"t":"⛵ 돛단배","mis":"M2-1-u5-X05"},{"t":"🚢 배","mis":"M2-1-u5-X05"}],"asset":{"type":"sort_bins","crit":"where","bins":[{"label":"땅","items":["🚌","🚌"]},{"label":"하늘","items":["🚗","✈️","✈️"]},{"label":"물","items":["⛵","🚢","⛵"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_challenge#2','math',2,1,'u5','L03','g2_1_math_u5_L03_challenge','lesson_challenge','M2-1-u5-C3',2,'mc','auto','동물을 다리 수에 따라 나눌 때 같은 칸에 들어가는 동물끼리 짝지은 것은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":2,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"동물을 다리 수에 따라 나눌 때 같은 칸에 들어가는 동물끼리 짝지은 것은 어느 것인가요?","options":[{"t":"🐔 닭 — 🐧 펭귄","correct":true},{"t":"🐔 닭 — 🐶 강아지","mis":"M2-1-u5-X05"},{"t":"🐟 물고기 — 🐦 새","mis":"M2-1-u5-X05"}],"explanation":["닭과 펭귄은 모두 다리가 2개예요.","강아지는 다리가 4개, 새는 2개, 물고기는 0개예요.","다리 수가 같아야 같은 칸이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_challenge#3','math',2,1,'u5','L03','g2_1_math_u5_L03_challenge','lesson_challenge','M2-1-u5-C3',3,'mc','auto','물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?',ARRAY['M2-1-u5-X05','M2-1-u5-X02']::text[],true,'{"seq":3,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?","explanation":["칸마다 움직이는 곳이 같아요: 가 땅, 나 하늘, 다 물.","바퀴 수는 한 칸 안에서도 서로 달라요.","칸 안의 물건이 모두 같은 특징을 찾으면 그것이 기준이에요."],"variant_rule":{"cls":{"ask":"crit","fams":["veh","tok"],"crits":["where","shape","color"]}},"options":[{"t":"움직이는 곳","correct":true},{"t":"바퀴 수","mis":"M2-1-u5-X05"},{"t":"빨라 보이는 것과 느려 보이는 것","mis":"M2-1-u5-X02"}],"asset":{"type":"sort_bins","bins":[{"label":"가","items":["🚲","🚲","🚌"]},{"label":"나","items":["🚁","✈️"]},{"label":"다","items":["⛵","🚤"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_challenge#4','math',2,1,'u5','L03','g2_1_math_u5_L03_challenge','lesson_challenge','M2-1-u5-C3',3,'mc','auto','모양에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],true,'{"seq":4,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"모양에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?","explanation":["파란 하트는 하트 모양인 것이에요.","그래서 「하트」 칸에 있어야 하는데 「네모」 칸에 들어가 있어요.","칸의 이름과 물건의 특징을 하나씩 맞춰 봐요."],"variant_rule":{"cls":{"ask":"odd","fams":["tok"],"crits":["shape","color"]}},"options":[{"t":"💙 파란 하트","correct":true},{"t":"💛 노란 하트","mis":"M2-1-u5-X05"},{"t":"🟩 초록 네모","mis":"M2-1-u5-X05"}],"asset":{"type":"sort_bins","crit":"shape","bins":[{"label":"동그라미","items":["🟢","🟢","🔴"]},{"label":"네모","items":["💙","🟩","🟨","🟦"]},{"label":"하트","items":["💛","💛"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_challenge#5','math',2,1,'u5','L03','g2_1_math_u5_L03_challenge','lesson_challenge','M2-1-u5-C3',3,'mc','auto','그림의 단추를 색깔에 따라 나누면 몇 가지, 모양에 따라 나누면 몇 가지가 될까요?',ARRAY['M2-1-u5-X05','M2-1-u5-X08']::text[],false,'{"seq":5,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"그림의 단추를 색깔에 따라 나누면 몇 가지, 모양에 따라 나누면 몇 가지가 될까요?","options":[{"t":"색깔 2가지, 모양 3가지","correct":true},{"t":"색깔 3가지, 모양 2가지","mis":"M2-1-u5-X05"},{"t":"색깔 4가지, 모양 4가지","mis":"M2-1-u5-X08"}],"explanation":["색깔은 빨간색과 파란색 2가지예요.","모양은 동그라미·네모·하트 3가지예요.","같은 단추도 기준이 다르면 나뉘는 가짓수가 달라요."],"asset":{"type":"sort_pile","items":["🔴","🟥","❤️","🔵"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_challenge#6','math',2,1,'u5','L03','g2_1_math_u5_L03_challenge','lesson_challenge','M2-1-u5-C3',3,'ox','auto','같은 물건이라도 기준을 바꾸어 나누면 나눈 결과가 달라질 수 있어요.',ARRAY['M2-1-u5-X04']::text[],false,'{"seq":6,"concept":"M2-1-u5-C3","difficulty":3,"kind":"ox","stem":"같은 물건이라도 기준을 바꾸어 나누면 나눈 결과가 달라질 수 있어요.","answer":"O","reason_options":[{"t":"기준마다 함께 모이는 물건이 달라지니까","correct":true},{"t":"같은 물건이니 언제나 결과가 같으니까","mis":"M2-1-u5-X04"}],"mis":"M2-1-u5-X04","explanation":["색깔로 나누면 같은 색끼리 모여요.","모양으로 나누면 같은 모양끼리 모여요.","그래서 결과가 달라질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_challenge#7','math',2,1,'u5','L03','g2_1_math_u5_L03_challenge','lesson_challenge','M2-1-u5-C3',3,'error','auto','친구들이 탈것을 움직이는 곳에 따라 나누었어요. 잘못 넣은 친구는 누구인가요?',ARRAY['M2-1-u5-X05','M2-1-u5-X12']::text[],false,'{"seq":7,"concept":"M2-1-u5-C3","difficulty":3,"kind":"error","stem":"친구들이 탈것을 움직이는 곳에 따라 나누었어요. 잘못 넣은 친구는 누구인가요?","options":[{"t":"지우 — 🚁 헬리콥터를 「땅」 칸에 넣었어요","correct":true,"mis_target":"M2-1-u5-X05"},{"t":"서아 — 🚢 배를 「물」 칸에 넣었어요","mis":"M2-1-u5-X12"},{"t":"하루 — 🚌 버스를 「땅」 칸에 넣었어요","mis":"M2-1-u5-X12"}],"explanation":["헬리콥터는 하늘을 날아요.","그래서 「하늘」 칸에 넣어야 해요.","배와 버스는 바르게 넣었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_challenge#8','math',2,1,'u5','L03','g2_1_math_u5_L03_challenge','lesson_challenge','M2-1-u5-C3',4,'mc','auto','그림에서 빨간색이면서 동그라미 모양인 단추는 몇 개일까요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":8,"concept":"M2-1-u5-C3","difficulty":4,"kind":"mc","stem":"그림에서 빨간색이면서 동그라미 모양인 단추는 몇 개일까요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M2-1-u5-X05"},{"t":"5개","mis":"M2-1-u5-X05"}],"explanation":["빨간색인 단추는 빨간 동그라미 3개, 빨간 네모 2개, 빨간 하트 1개로 6개예요.","그 가운데 동그라미 모양은 3개예요.","두 가지 특징을 모두 갖춘 것만 세어요."],"asset":{"type":"sort_pile","items":["🔴","🟥","🔵","🔴","❤️","🟡","🟥","🔴"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_challenge#9','math',2,1,'u5','L03','g2_1_math_u5_L03_challenge','lesson_challenge','M2-1-u5-C3',4,'essay','teacher','그림의 단추를 서로 다른 두 가지 기준으로 나누려고 해요. 기준을 두 가지 쓰고, 각 기준으로 나누면 어떤 칸들이 생기는지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u5-C3","difficulty":4,"kind":"essay","stem":"그림의 단추를 서로 다른 두 가지 기준으로 나누려고 해요. 기준을 두 가지 쓰고, 각 기준으로 나누면 어떤 칸들이 생기는지 써 보세요.","answer_guide":{"answer":"예: 색깔로 나누면 빨간색·파란색·노란색 칸이 생긴다. 모양으로 나누면 동그라미·네모·하트 칸이 생긴다.","scoring_points":["분명한 기준 두 가지를 썼는가","각 기준으로 생기는 칸의 이름을 바르게 썼는가","기준이 다르면 나뉘는 모습이 다름을 알았는가"]},"explanation":["색깔과 모양은 분명한 기준이에요.","기준마다 칸이 달라요.","같은 단추도 두 가지로 나눌 수 있어요."],"asset":{"type":"sort_pile","items":["🔴","🟦","💛","🟥","🔵","🟨","❤️","💙","🟡"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L03_challenge#10','math',2,1,'u5','L03','g2_1_math_u5_L03_challenge','lesson_challenge','M2-1-u5-C3',4,'essay','teacher','어떤 친구가 단추를 「빨간 것」 칸과 「동그라미 모양」 칸으로 나누었어요. 이렇게 나누면 어떤 문제가 생기는지 🔴 빨간 동그라미를 예로 들어 쓰고, 바르게 나누는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u5-C3","difficulty":4,"kind":"essay","stem":"어떤 친구가 단추를 「빨간 것」 칸과 「동그라미 모양」 칸으로 나누었어요. 이렇게 나누면 어떤 문제가 생기는지 🔴 빨간 동그라미를 예로 들어 쓰고, 바르게 나누는 방법을 써 보세요.","answer_guide":{"answer":"예: 빨간 동그라미는 빨간 것이면서 동그라미여서 두 칸 모두에 들어갈 수 있어 어디에 넣을지 헷갈리고 두 번 셀 수 있다. 색깔이면 색깔끼리, 모양이면 모양끼리 한 가지 기준으로 칸을 정해야 한다.","scoring_points":["한 물건이 두 칸에 들어갈 수 있다는 문제를 썼는가","빨간 동그라미를 예로 들었는가","한 가지 기준으로 칸을 정해야 한다고 썼는가"]},"explanation":["두 기준을 섞으면 칸이 겹쳐요.","한 물건이 두 칸에 들어갈 수 있어요.","한 가지 기준으로 칸을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_basic#1','math',2,1,'u5','L04','g2_1_math_u5_L04_basic','lesson_basic','M2-1-u5-C4',1,'mc','auto','분류한 물건을 빠뜨리지 않고 세려면 어떻게 해야 할까요?',ARRAY['M2-1-u5-X06']::text[],true,'{"seq":1,"concept":"M2-1-u5-C4","difficulty":1,"kind":"mc","stem":"분류한 물건을 빠뜨리지 않고 세려면 어떻게 해야 할까요?","options":[{"t":"하나 셀 때마다 ／ 표시를 해요","correct":true},{"t":"표시 없이 눈으로만 빠르게 세요","mis":"M2-1-u5-X06"},{"t":"마음에 드는 것만 세요","mis":"M2-1-u5-X06"}],"explanation":["세면서 표시하면 센 것과 안 센 것이 구별돼요.","그래서 빠뜨리거나 두 번 세지 않아요.","다 센 뒤 표시 수와 물건 수를 견주어 봐요."],"variant_rule":{"alt":[{"stem":"분류한 물건을 세다가 어디까지 셌는지 헷갈렸어요. 처음부터 어떻게 세면 좋을까요?","options":[{"t":"센 물건에 하나씩 ／ 표시를 하며 세요","correct":true},{"t":"눈대중으로 대강 세요","mis":"M2-1-u5-X06"},{"t":"큰 것만 골라 세요","mis":"M2-1-u5-X06"}],"explanation":["표시를 하면 센 것을 다시 세지 않아요.","빠뜨린 것도 바로 보여요.","／ 표시는 빠짐없이 세는 방법이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_basic#2','math',2,1,'u5','L04','g2_1_math_u5_L04_basic','lesson_basic','M2-1-u5-C4',1,'mc','auto','사과는 몇 개일까요?',ARRAY['M2-1-u5-X06']::text[],true,'{"seq":2,"concept":"M2-1-u5-C4","difficulty":1,"kind":"mc","stem":"사과는 몇 개일까요?","explanation":["사과만 골라 하나씩 ／ 표시를 하며 세어요.","사과는 4개예요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"cls":{"ask":"count","fams":["fruit","ani","veh"]}},"options":[{"t":"4개","correct":true},{"t":"5개","mis":"M2-1-u5-X06"},{"t":"3개","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_pile","items":["🍇","🍊","🍎","🍎","🍊","🍇","🍎","🍊","🍎"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_basic#3','math',2,1,'u5','L04','g2_1_math_u5_L04_basic','lesson_basic','M2-1-u5-C4',1,'sa','auto','아래옷은 몇 벌일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-1-u5-C4","difficulty":1,"kind":"sa","stem":"아래옷은 몇 벌일까요? 숫자로 쓰세요.","explanation":["아래옷만 골라 하나씩 ／ 표시를 하며 세어요.","아래옷은 3벌이에요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"cls":{"ask":"count","fams":["cloth","book","sup"]}},"answer":["3","3벌"],"asset":{"type":"sort_pile","items":["👖","🧥","👚","👕","👖","🧥","👚","🩳"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_basic#4','math',2,1,'u5','L04','g2_1_math_u5_L04_basic','lesson_basic','M2-1-u5-C4',1,'mc','auto','／ 표시를 보고 수를 읽으세요. 「／／／／／ ／／」는 몇일까요?',ARRAY['M2-1-u5-X13']::text[],true,'{"seq":4,"concept":"M2-1-u5-C4","difficulty":1,"kind":"mc","stem":"／ 표시를 보고 수를 읽으세요. 「／／／／／ ／／」는 몇일까요?","options":[{"t":"7","correct":true},{"t":"2","mis":"M2-1-u5-X13"},{"t":"6","mis":"M2-1-u5-X13"}],"explanation":["／ 다섯 개가 한 묶음이에요.","5와 2를 이어 세면 7이에요.","묶음 하나는 5로 세어요."],"variant_rule":{"alt":[{"stem":"／ 표시를 보고 수를 읽으세요. 「／／／／／ ／／／／」는 몇일까요?","options":[{"t":"9","correct":true},{"t":"4","mis":"M2-1-u5-X13"},{"t":"8","mis":"M2-1-u5-X13"}],"explanation":["／ 다섯 개가 한 묶음이에요.","5와 4를 이어 세면 9예요.","묶음 하나는 5로 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_basic#5','math',2,1,'u5','L04','g2_1_math_u5_L04_basic','lesson_basic','M2-1-u5-C4',2,'sa','auto','그림의 동물은 모두 몇 마리일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-1-u5-C4","difficulty":2,"kind":"sa","stem":"그림의 동물은 모두 몇 마리일까요? 숫자로 쓰세요.","explanation":["다리 수에 따라 나누어 세면 다리 0개 2마리, 다리 2개 3마리, 다리 4개 4마리예요.","2 + 3 + 4 = 9이니 모두 9마리예요.","각 칸의 수를 모두 더하면 전체 수와 같아요."],"variant_rule":{"cls":{"ask":"total","fams":["ani","tok","fruit"]}},"answer":["9","9마리"],"asset":{"type":"sort_pile","items":["🐔","🐮","🐱","🐬","🐍","🦆","🦆","🐮","🐮"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_basic#6','math',2,1,'u5','L04','g2_1_math_u5_L04_basic','lesson_basic','M2-1-u5-C4',2,'sa','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-1-u5-C4","difficulty":2,"kind":"sa","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.","explanation":["「빨간색」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／ → 6","그래서 빈칸은 6이에요."],"variant_rule":{"cls":{"ask":"tally","fams":["tok","book","recy"]}},"answer":["6"],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","파란색","노란색"],"counts":[null,4,3],"unit":"개","tally":[6,4,3]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_basic#7','math',2,1,'u5','L04','g2_1_math_u5_L04_basic','lesson_basic','M2-1-u5-C4',2,'ox','auto','분류한 각 칸의 수를 모두 더하면 전체 수와 같아요.',ARRAY['M2-1-u5-X07']::text[],true,'{"seq":7,"concept":"M2-1-u5-C4","difficulty":2,"kind":"ox","stem":"분류한 각 칸의 수를 모두 더하면 전체 수와 같아요.","answer":"O","reason_options":[{"t":"모든 물건이 한 칸씩에 들어가 있으니까","correct":true},{"t":"가장 많은 칸의 수가 전체 수니까","mis":"M2-1-u5-X07"}],"mis":"M2-1-u5-X07","explanation":["물건마다 꼭 한 칸에 들어가 있어요.","그래서 각 칸의 수를 더하면 전체 수예요.","다 센 뒤 더해서 맞는지 확인해요."],"variant_rule":{"alt":[{"stem":"분류하여 세면 전체 물건이 몇 개인지는 알 수 없어요.","answer":"X","reason_options":[{"t":"각 칸의 수를 모두 더하면 전체 수가 되니까","correct":true},{"t":"나누어 놓았으니 전체는 셀 수 없으니까","mis":"M2-1-u5-X07"}],"explanation":["나누어 세어도 전체 수를 알 수 있어요.","각 칸의 수를 모두 더하면 돼요.","전체 수가 맞는지 확인할 때도 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_basic#8','math',2,1,'u5','L04','g2_1_math_u5_L04_basic','lesson_basic','M2-1-u5-C4',2,'mc','auto','네모 모양인 것은 몇 개일까요?',ARRAY['M2-1-u5-X06']::text[],true,'{"seq":8,"concept":"M2-1-u5-C4","difficulty":2,"kind":"mc","stem":"네모 모양인 것은 몇 개일까요?","explanation":["네모 모양인 것만 골라 하나씩 ／ 표시를 하며 세어요.","네모 모양인 것은 3개예요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"cls":{"ask":"count","fams":["tok"]}},"options":[{"t":"3개","correct":true},{"t":"4개","mis":"M2-1-u5-X06"},{"t":"2개","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_pile","items":["❤️","🟡","🟡","🟨","❤️","🟡","🟢","🟩","🟥"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_basic#9','math',2,1,'u5','L04','g2_1_math_u5_L04_basic','lesson_basic','M2-1-u5-C4',2,'mc','auto','표를 보세요. 분류한 책은 모두 몇 권일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X08']::text[],true,'{"seq":9,"concept":"M2-1-u5-C4","difficulty":2,"kind":"mc","stem":"표를 보세요. 분류한 책은 모두 몇 권일까요?","explanation":["각 칸의 수는 빨간색 5권, 초록색 3권, 파란색 4권이에요.","5 + 3 + 4 = 12이니 모두 12권이에요.","각 칸의 수를 모두 더하면 전체 수와 같아요."],"variant_rule":{"cls":{"ask":"total","src":"table","fams":["book","sup","recy"]}},"options":[{"t":"12권","correct":true},{"t":"5권","mis":"M2-1-u5-X07"},{"t":"3권","mis":"M2-1-u5-X08"}],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","초록색","파란색"],"counts":[5,3,4],"unit":"권"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_basic#10','math',2,1,'u5','L04','g2_1_math_u5_L04_basic','lesson_basic','M2-1-u5-C4',3,'mc','auto','표의 빈칸에 알맞은 수는 얼마일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X06']::text[],true,'{"seq":10,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"표의 빈칸에 알맞은 수는 얼마일까요?","explanation":["나머지 칸을 더하면 6 + 2 = 8이에요.","8 + □ = 12이니 □ = 4예요.","각 칸의 수를 모두 더하면 합계와 같아요."],"variant_rule":{"cls":{"ask":"blank","src":"table","fams":["sup","fruit","ani"]}},"options":[{"t":"4","correct":true},{"t":"12","mis":"M2-1-u5-X07"},{"t":"5","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_table","crit":"kind","cols":["연필","자","공책"],"counts":[6,2,null],"unit":"개","total":12}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_challenge#1','math',2,1,'u5','L04','g2_1_math_u5_L04_challenge','lesson_challenge','M2-1-u5-C4',2,'mc','auto','바퀴가 2개인 탈것은 몇 대일까요?',ARRAY['M2-1-u5-X06']::text[],true,'{"seq":1,"concept":"M2-1-u5-C4","difficulty":2,"kind":"mc","stem":"바퀴가 2개인 탈것은 몇 대일까요?","explanation":["바퀴가 2개인 탈것만 골라 하나씩 ／ 표시를 하며 세어요.","바퀴가 2개인 탈것은 3대예요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"cls":{"ask":"count","fams":["veh"],"crits":["wheels"]}},"options":[{"t":"3대","correct":true},{"t":"4대","mis":"M2-1-u5-X06"},{"t":"2대","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_pile","items":["🚗","🚲","🚌","🚌","🚲","🚌","🚗","🚲"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_challenge#2','math',2,1,'u5','L04','g2_1_math_u5_L04_challenge','lesson_challenge','M2-1-u5-C4',2,'mc','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요?',ARRAY['M2-1-u5-X13','M2-1-u5-X06']::text[],true,'{"seq":2,"concept":"M2-1-u5-C4","difficulty":2,"kind":"mc","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요?","explanation":["「플라스틱」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／／／ → 8","그래서 빈칸은 8이에요."],"variant_rule":{"cls":{"ask":"tally","fams":["recy","fruit","tok"]}},"options":[{"t":"8","correct":true},{"t":"7","mis":"M2-1-u5-X13"},{"t":"9","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_table","crit":"kind","cols":["캔","플라스틱","종이"],"counts":[5,null,6],"unit":"개","tally":[5,8,6]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_challenge#3','math',2,1,'u5','L04','g2_1_math_u5_L04_challenge','lesson_challenge','M2-1-u5-C4',3,'mc','auto','그림의 단추는 모두 몇 개일까요?',ARRAY['M2-1-u5-X06']::text[],true,'{"seq":3,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"그림의 단추는 모두 몇 개일까요?","explanation":["색깔에 따라 나누어 세면 빨간색 3개, 파란색 4개, 노란색 2개, 초록색 3개예요.","3 + 4 + 2 + 3 = 12이니 모두 12개예요.","각 칸의 수를 모두 더하면 전체 수와 같아요."],"variant_rule":{"cls":{"ask":"total","fams":["tok","ani","veh"]}},"options":[{"t":"12개","correct":true},{"t":"13개","mis":"M2-1-u5-X06"},{"t":"11개","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_pile","items":["🟥","💚","💚","🔵","💙","💛","🟥","🟡","💙","🔵","❤️","🟢"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_challenge#4','math',2,1,'u5','L04','g2_1_math_u5_L04_challenge','lesson_challenge','M2-1-u5-C4',3,'sa','auto','표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-1-u5-C4","difficulty":3,"kind":"sa","stem":"표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.","explanation":["나머지 칸을 더하면 3 + 6 = 9예요.","9 + □ = 14이니 □ = 5예요.","각 칸의 수를 모두 더하면 합계와 같아요."],"variant_rule":{"cls":{"ask":"blank","src":"table","fams":["ani","book","cloth"]}},"answer":["5"],"asset":{"type":"sort_table","crit":"legs","cols":["다리 0개","다리 2개","다리 4개"],"counts":[3,null,6],"unit":"마리","total":14}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_challenge#5','math',2,1,'u5','L04','g2_1_math_u5_L04_challenge','lesson_challenge','M2-1-u5-C4',3,'error','auto','친구들이 분류한 물건을 센 방법을 말했어요. 잘못 센 친구는 누구인가요?',ARRAY['M2-1-u5-X06','M2-1-u5-X12']::text[],false,'{"seq":5,"concept":"M2-1-u5-C4","difficulty":3,"kind":"error","stem":"친구들이 분류한 물건을 센 방법을 말했어요. 잘못 센 친구는 누구인가요?","options":[{"t":"다예 — 「표시 없이 세다가 같은 것을 한 번 더 셌어.」","correct":true,"mis_target":"M2-1-u5-X06"},{"t":"곰이 — 「하나 셀 때마다 ／ 표시를 했어.」","mis":"M2-1-u5-X12"},{"t":"펭이 — 「다 센 뒤 칸의 수를 더해 전체 수와 맞춰 봤어.」","mis":"M2-1-u5-X12"}],"explanation":["같은 것을 두 번 세면 수가 커져요.","다예가 잘못 세었어요.","／ 표시와 합 확인은 바르게 세는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_challenge#6','math',2,1,'u5','L04','g2_1_math_u5_L04_challenge','lesson_challenge','M2-1-u5-C4',3,'mc','auto','단추 12개를 색깔에 따라 나누었더니 빨간색 5개, 파란색 4개였어요. 나머지는 모두 노란색이에요. 노란색 단추는 몇 개일까요?',ARRAY['M2-1-u5-X07']::text[],false,'{"seq":6,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"단추 12개를 색깔에 따라 나누었더니 빨간색 5개, 파란색 4개였어요. 나머지는 모두 노란색이에요. 노란색 단추는 몇 개일까요?","options":[{"t":"3개","correct":true},{"t":"12개","mis":"M2-1-u5-X07"},{"t":"9개","mis":"M2-1-u5-X07"}],"explanation":["빨간색과 파란색은 5 + 4 = 9개예요.","전체 12개에서 9개를 빼면 3개예요.","각 칸의 수를 모두 더하면 전체 수가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_challenge#7','math',2,1,'u5','L04','g2_1_math_u5_L04_challenge','lesson_challenge','M2-1-u5-C4',3,'mc','auto','그림의 탈것을 움직이는 곳에 따라 분류하면 몇 가지로 나눌 수 있을까요?',ARRAY['M2-1-u5-X08','M2-1-u5-X03']::text[],true,'{"seq":7,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"그림의 탈것을 움직이는 곳에 따라 분류하면 몇 가지로 나눌 수 있을까요?","explanation":["움직이는 곳을 살펴보면 땅, 하늘, 물이 있어요.","그래서 3가지로 나눌 수 있어요.","물건의 수(8대)가 아니라 칸이 몇 가지인지 세어요."],"variant_rule":{"cls":{"ask":"groups","fams":["veh","ani","tok"]}},"options":[{"t":"3가지","correct":true},{"t":"8가지","mis":"M2-1-u5-X08"},{"t":"4가지","mis":"M2-1-u5-X03"}],"asset":{"type":"sort_pile","items":["⛵","✈️","🛵","🚌","🚲","🚢","⛵","🚁"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_challenge#8','math',2,1,'u5','L04','g2_1_math_u5_L04_challenge','lesson_challenge','M2-1-u5-C4',4,'mc','auto','책 12권을 색깔에 따라 나누었더니 빨간색 4권, 초록색 3권, 파란색 5권이었어요. 같은 책을 다시 종류에 따라 나누었더니 동화책이 7권이고 나머지는 모두 과학책이었어요. 과학책은 몇 권일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X04']::text[],false,'{"seq":8,"concept":"M2-1-u5-C4","difficulty":4,"kind":"mc","stem":"책 12권을 색깔에 따라 나누었더니 빨간색 4권, 초록색 3권, 파란색 5권이었어요. 같은 책을 다시 종류에 따라 나누었더니 동화책이 7권이고 나머지는 모두 과학책이었어요. 과학책은 몇 권일까요?","options":[{"t":"5권","correct":true},{"t":"12권","mis":"M2-1-u5-X07"},{"t":"3권","mis":"M2-1-u5-X04"}],"explanation":["기준을 바꾸어 나누어도 전체 책은 12권 그대로예요.","12권 가운데 동화책 7권을 빼면 과학책은 5권이에요.","기준이 달라도 각 칸의 수를 더하면 전체 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_challenge#9','math',2,1,'u5','L04','g2_1_math_u5_L04_challenge','lesson_challenge','M2-1-u5-C4',4,'essay','teacher','분류한 것을 셀 때 하나 셀 때마다 ／ 표시를 하는 까닭과, ／ 표시를 다섯 개씩 묶어 두면 좋은 점을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u5-C4","difficulty":4,"kind":"essay","stem":"분류한 것을 셀 때 하나 셀 때마다 ／ 표시를 하는 까닭과, ／ 표시를 다섯 개씩 묶어 두면 좋은 점을 써 보세요.","answer_guide":{"answer":"예: 표시를 하면 센 것과 안 센 것이 구별되어 빠뜨리거나 두 번 세지 않는다. 다섯 개씩 묶어 두면 5, 10처럼 묶음으로 세어 한눈에 수를 알 수 있다.","scoring_points":["빠뜨리거나 두 번 세지 않는다는 까닭을 썼는가","다섯 개씩 묶으면 5씩 세어 빠르고 한눈에 보인다고 썼는가","예를 들어 설명했는가"]},"explanation":["표시는 센 것을 알려 줘요.","다섯 묶음은 5로 세어요.","빠짐없이, 한눈에 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L04_challenge#10','math',2,1,'u5','L04','g2_1_math_u5_L04_challenge','lesson_challenge','M2-1-u5-C4',4,'sa','auto','그림에서 빨간색이면서 하트 모양인 단추는 몇 개일까요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u5-C4","difficulty":4,"kind":"sa","stem":"그림에서 빨간색이면서 하트 모양인 단추는 몇 개일까요? 숫자로 쓰세요.","answer":["3"],"explanation":["빨간색 단추는 빨간 하트 3개와 빨간 동그라미 2개, 빨간 네모 1개예요.","그 가운데 하트 모양은 3개예요.","두 가지 특징을 모두 갖춘 것만 세어요."],"asset":{"type":"sort_pile","items":["❤️","🔴","💛","❤️","🟥","💙","❤️","🔴","💚"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_basic#1','math',2,1,'u5','L05','g2_1_math_u5_L05_basic','lesson_basic','M2-1-u5-C5',1,'mc','auto','색깔에 따라 분류했을 때 가장 많은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":1,"concept":"M2-1-u5-C5","difficulty":1,"kind":"mc","stem":"색깔에 따라 분류했을 때 가장 많은 것은 무엇일까요?","explanation":["색깔에 따라 세면 빨간색 5권, 초록색 9권, 파란색 6권이에요.","수가 가장 큰 칸은 초록색(9권)이에요.","「가장 많은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"most","src":"table","fams":["book","fruit","tok"]}},"options":[{"t":"초록색","correct":true},{"t":"빨간색","mis":"M2-1-u5-X12"},{"t":"파란색","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","초록색","파란색"],"counts":[5,9,6],"unit":"권"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_basic#2','math',2,1,'u5','L05','g2_1_math_u5_L05_basic','lesson_basic','M2-1-u5-C5',1,'mc','auto','종류에 따라 분류했을 때 가장 적은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":2,"concept":"M2-1-u5-C5","difficulty":1,"kind":"mc","stem":"종류에 따라 분류했을 때 가장 적은 것은 무엇일까요?","explanation":["종류에 따라 세면 사과 4개, 귤 6개, 바나나 3개예요.","수가 가장 작은 칸은 바나나(3개)예요.","「가장 적은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"least","src":"table","fams":["fruit","recy","sup"]}},"options":[{"t":"바나나","correct":true},{"t":"귤","mis":"M2-1-u5-X12"},{"t":"사과","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","바나나"],"counts":[4,6,3],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_basic#3','math',2,1,'u5','L05','g2_1_math_u5_L05_basic','lesson_basic','M2-1-u5-C5',1,'sa','auto','종이는 몇 개일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-1-u5-C5","difficulty":1,"kind":"sa","stem":"종이는 몇 개일까요? 숫자로 쓰세요.","explanation":["표에서 「종이」 칸의 수를 읽어요.","종이는 6개예요.","칸 이름과 그 아래 수를 짝지어 읽어요."],"variant_rule":{"cls":{"ask":"count","src":"table","fams":["recy","ani","cloth"]}},"answer":["6","6개"],"asset":{"type":"sort_table","crit":"kind","cols":["캔","플라스틱","종이"],"counts":[5,8,6],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_basic#4','math',2,1,'u5','L05','g2_1_math_u5_L05_basic','lesson_basic','M2-1-u5-C5',1,'mc','auto','책을 종류에 따라 나누어 센 표를 보고 알 수 있는 것은 어느 것인가요?',ARRAY['M2-1-u5-X09']::text[],true,'{"seq":4,"concept":"M2-1-u5-C5","difficulty":1,"kind":"mc","stem":"책을 종류에 따라 나누어 센 표를 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"어느 종류의 책이 가장 많은지","correct":true},{"t":"책을 누가 빌려 갔는지","mis":"M2-1-u5-X09"},{"t":"책을 산 날짜","mis":"M2-1-u5-X09"}],"explanation":["표에는 종류와 권수가 있어요.","그래서 어느 종류가 가장 많은지 알 수 있어요.","누가 빌렸는지, 언제 샀는지는 표에 없어요."],"asset":{"type":"sort_table","crit":"kind","cols":["인물 이야기","그림 동화","신기한 과학"],"counts":[5,9,6],"unit":"권"},"variant_rule":{"alt":[{"stem":"과일을 종류에 따라 나누어 센 표를 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"과일이 모두 몇 개인지","correct":true},{"t":"과일을 어디에서 샀는지","mis":"M2-1-u5-X09"},{"t":"과일이 얼마나 단지","mis":"M2-1-u5-X09"}],"explanation":["표의 수를 모두 더하면 전체 개수를 알 수 있어요.","4 + 6 + 3 = 13개예요.","어디서 샀는지, 얼마나 단지는 표에 없어요."],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","바나나"],"counts":[4,6,3],"unit":"개"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_basic#5','math',2,1,'u5','L05','g2_1_math_u5_L05_basic','lesson_basic','M2-1-u5-C5',2,'sa','auto','표를 보세요. 분류한 옷은 모두 몇 벌일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-1-u5-C5","difficulty":2,"kind":"sa","stem":"표를 보세요. 분류한 옷은 모두 몇 벌일까요? 숫자로 쓰세요.","explanation":["각 칸의 수는 윗옷 7벌, 아래옷 5벌이에요.","7 + 5 = 12이니 모두 12벌이에요.","각 칸의 수를 모두 더하면 전체 수와 같아요."],"variant_rule":{"cls":{"ask":"total","src":"table","fams":["cloth","book","fruit"]}},"answer":["12","12벌"],"asset":{"type":"sort_table","crit":"part","cols":["윗옷","아래옷"],"counts":[7,5],"unit":"벌"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_basic#6','math',2,1,'u5','L05','g2_1_math_u5_L05_basic','lesson_basic','M2-1-u5-C5',2,'sa','auto','귤은 사과보다 몇 개 더 많을까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-1-u5-C5","difficulty":2,"kind":"sa","stem":"귤은 사과보다 몇 개 더 많을까요? 숫자로 쓰세요.","explanation":["귤은 7개, 사과는 4개예요.","7 − 4 = 3이니 3개 더 많아요.","「더 많은」 수는 두 수의 차이예요. 더하지 않아요."],"variant_rule":{"cls":{"ask":"diff","src":"table","fams":["fruit","book","ani"]}},"answer":["3","3개"],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","포도"],"counts":[4,7,5],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_basic#7','math',2,1,'u5','L05','g2_1_math_u5_L05_basic','lesson_basic','M2-1-u5-C5',2,'ox','auto','분류한 결과 표에서는 맨 앞(왼쪽) 칸이 언제나 가장 많아요.',ARRAY['M2-1-u5-X10']::text[],true,'{"seq":7,"concept":"M2-1-u5-C5","difficulty":2,"kind":"ox","stem":"분류한 결과 표에서는 맨 앞(왼쪽) 칸이 언제나 가장 많아요.","answer":"X","reason_options":[{"t":"수가 가장 큰 칸이 가장 많은 것이니까","correct":true},{"t":"먼저 쓴 칸이 가장 많은 것이니까","mis":"M2-1-u5-X10"}],"mis":"M2-1-u5-X10","explanation":["칸의 순서는 많고 적음과 상관없어요.","칸 아래의 수끼리 견주어야 해요.","수가 가장 큰 칸이 가장 많아요."],"variant_rule":{"alt":[{"stem":"분류한 결과 표에서 수가 가장 큰 칸이 가장 많은 것이에요.","answer":"O","reason_options":[{"t":"수가 클수록 그 칸의 물건이 많으니까","correct":true},{"t":"칸 이름이 가장 긴 것이 가장 많으니까","mis":"M2-1-u5-X10"}],"explanation":["칸 아래의 수가 그 칸의 물건 수예요.","수가 가장 큰 칸이 가장 많아요.","이름의 길이나 칸의 자리와는 상관없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_basic#8','math',2,1,'u5','L05','g2_1_math_u5_L05_basic','lesson_basic','M2-1-u5-C5',2,'mc','auto','다리 수에 따라 분류했을 때 가장 많은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":8,"concept":"M2-1-u5-C5","difficulty":2,"kind":"mc","stem":"다리 수에 따라 분류했을 때 가장 많은 것은 무엇일까요?","explanation":["다리 수에 따라 세면 다리 0개 2마리, 다리 2개 5마리, 다리 4개 3마리예요.","수가 가장 큰 칸은 다리 2개(5마리)예요.","「가장 많은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"most","fams":["ani","tok","veh"]}},"options":[{"t":"다리 2개","correct":true},{"t":"다리 0개","mis":"M2-1-u5-X12"},{"t":"다리 4개","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_pile","items":["🦆","🐶","🐍","🐶","🦆","🦆","🐧","🐷","🐬","🐔"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_basic#9','math',2,1,'u5','L05','g2_1_math_u5_L05_basic','lesson_basic','M2-1-u5-C5',2,'mc','auto','학급 문고의 책을 종류에 따라 세었어요. 책을 더 사서 가장 적은 종류를 채우려고 해요. 어떤 책을 사면 좋을까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":9,"concept":"M2-1-u5-C5","difficulty":2,"kind":"mc","stem":"학급 문고의 책을 종류에 따라 세었어요. 책을 더 사서 가장 적은 종류를 채우려고 해요. 어떤 책을 사면 좋을까요?","options":[{"t":"위인전","correct":true},{"t":"동화책","mis":"M2-1-u5-X12"},{"t":"과학책","mis":"M2-1-u5-X10"}],"explanation":["표를 보면 동화책 9권, 위인전 5권, 과학책 6권이에요.","가장 적은 것은 위인전이에요.","분류한 결과로 무엇을 채울지 정할 수 있어요."],"asset":{"type":"sort_table","crit":"kind","cols":["동화책","위인전","과학책"],"counts":[9,5,6],"unit":"권"},"variant_rule":{"alt":[{"stem":"교실 공을 종류에 따라 세었어요. 공을 하나 더 사서 가장 적은 종류를 채우려고 해요. 어떤 공을 사면 좋을까요?","options":[{"t":"농구공","correct":true},{"t":"축구공","mis":"M2-1-u5-X12"},{"t":"배구공","mis":"M2-1-u5-X10"}],"explanation":["표를 보면 축구공 6개, 농구공 2개, 배구공 4개예요.","가장 적은 것은 농구공이에요.","분류한 결과로 무엇을 채울지 정할 수 있어요."],"asset":{"type":"sort_table","crit":"kind","cols":["축구공","농구공","배구공"],"counts":[6,2,4],"unit":"개"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_basic#10','math',2,1,'u5','L05','g2_1_math_u5_L05_basic','lesson_basic','M2-1-u5-C5',3,'mc','auto','빨간색인 것은 파란색인 것보다 몇 개 더 많을까요?',ARRAY['M2-1-u5-X11']::text[],true,'{"seq":10,"concept":"M2-1-u5-C5","difficulty":3,"kind":"mc","stem":"빨간색인 것은 파란색인 것보다 몇 개 더 많을까요?","explanation":["빨간색인 것은 6개, 파란색인 것은 2개예요.","6 − 2 = 4이니 4개 더 많아요.","「더 많은」 수는 두 수의 차이예요. 더하지 않아요."],"variant_rule":{"cls":{"ask":"diff","fams":["tok","fruit","ani"]}},"options":[{"t":"4개","correct":true},{"t":"8개","mis":"M2-1-u5-X11"},{"t":"6개","mis":"M2-1-u5-X11"}],"asset":{"type":"sort_pile","items":["❤️","🟥","🔴","🔴","❤️","🟡","🔴","🟦","🟡","🟡","🔵","🟡"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_challenge#1','math',2,1,'u5','L05','g2_1_math_u5_L05_challenge','lesson_challenge','M2-1-u5-C5',2,'mc','auto','움직이는 곳에 따라 분류했을 때 가장 적은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":1,"concept":"M2-1-u5-C5","difficulty":2,"kind":"mc","stem":"움직이는 곳에 따라 분류했을 때 가장 적은 것은 무엇일까요?","explanation":["움직이는 곳에 따라 세면 땅 5대, 하늘 2대, 물 3대예요.","수가 가장 작은 칸은 하늘(2대)이에요.","「가장 적은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"least","fams":["veh","tok","fruit"]}},"options":[{"t":"하늘","correct":true},{"t":"땅","mis":"M2-1-u5-X12"},{"t":"물","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_pile","items":["⛵","🚌","🚌","✈️","🚕","⛵","⛵","✈️","🚌","🚗"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_challenge#2','math',2,1,'u5','L05','g2_1_math_u5_L05_challenge','lesson_challenge','M2-1-u5-C5',2,'ox','auto','분류하여 센 결과를 보면 가장 많은 것과 가장 적은 것을 알 수 있어요.',ARRAY['M2-1-u5-X09']::text[],false,'{"seq":2,"concept":"M2-1-u5-C5","difficulty":2,"kind":"ox","stem":"분류하여 센 결과를 보면 가장 많은 것과 가장 적은 것을 알 수 있어요.","answer":"O","reason_options":[{"t":"칸마다 수가 있어 서로 견줄 수 있으니까","correct":true},{"t":"물건을 언제 샀는지도 알 수 있으니까","mis":"M2-1-u5-X09"}],"mis":"M2-1-u5-X09","explanation":["분류한 결과에는 칸마다 수가 있어요.","수를 견주면 가장 많은 것과 적은 것을 알아요.","언제 샀는지는 결과에 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_challenge#3','math',2,1,'u5','L05','g2_1_math_u5_L05_challenge','lesson_challenge','M2-1-u5-C5',3,'sa','auto','다리가 2개인 동물은 다리가 0개인 동물보다 몇 마리 더 많을까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-1-u5-C5","difficulty":3,"kind":"sa","stem":"다리가 2개인 동물은 다리가 0개인 동물보다 몇 마리 더 많을까요? 숫자로 쓰세요.","explanation":["다리가 2개인 동물은 8마리, 다리가 0개인 동물은 3마리예요.","8 − 3 = 5이니 5마리 더 많아요.","「더 많은」 수는 두 수의 차이예요. 더하지 않아요."],"variant_rule":{"cls":{"ask":"diff","src":"table","fams":["ani","recy","book"]}},"answer":["5","5마리"],"asset":{"type":"sort_table","crit":"legs","cols":["다리 0개","다리 2개","다리 4개"],"counts":[3,8,5],"unit":"마리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_challenge#4','math',2,1,'u5','L05','g2_1_math_u5_L05_challenge','lesson_challenge','M2-1-u5-C5',3,'mc','auto','표의 빈칸에 알맞은 수는 얼마일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X06']::text[],true,'{"seq":4,"concept":"M2-1-u5-C5","difficulty":3,"kind":"mc","stem":"표의 빈칸에 알맞은 수는 얼마일까요?","explanation":["나머지 칸을 더하면 4 + 3 = 7이에요.","7 + □ = 13이니 □ = 6이에요.","각 칸의 수를 모두 더하면 합계와 같아요."],"variant_rule":{"cls":{"ask":"blank","src":"table","fams":["fruit","tok","sup"]}},"options":[{"t":"6","correct":true},{"t":"13","mis":"M2-1-u5-X07"},{"t":"7","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","바나나"],"counts":[4,null,3],"unit":"개","total":13}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_challenge#5','math',2,1,'u5','L05','g2_1_math_u5_L05_challenge','lesson_challenge','M2-1-u5-C5',3,'error','auto','과일을 종류에 따라 세었더니 사과 4개, 귤 6개, 바나나 3개였어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u5-X12','M2-1-u5-X07','M2-1-u5-X11']::text[],false,'{"seq":5,"concept":"M2-1-u5-C5","difficulty":3,"kind":"error","stem":"과일을 종류에 따라 세었더니 사과 4개, 귤 6개, 바나나 3개였어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 「바나나가 가장 많아.」","correct":true,"mis_target":"M2-1-u5-X12"},{"t":"서윤 — 「과일은 모두 13개야.」","mis":"M2-1-u5-X07"},{"t":"도윤 — 「귤이 사과보다 2개 더 많아.」","mis":"M2-1-u5-X11"}],"explanation":["바나나는 3개로 가장 적어요.","가장 많은 것은 6개인 귤이에요.","4 + 6 + 3 = 13, 6 − 4 = 2이니 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_challenge#6','math',2,1,'u5','L05','g2_1_math_u5_L05_challenge','lesson_challenge','M2-1-u5-C5',3,'mc','auto','조각보에 쓴 조각을 색깔에 따라 세었어요. 두 번째로 많이 쓴 색은 무엇일까요?',ARRAY['M2-1-u5-X10']::text[],false,'{"seq":6,"concept":"M2-1-u5-C5","difficulty":3,"kind":"mc","stem":"조각보에 쓴 조각을 색깔에 따라 세었어요. 두 번째로 많이 쓴 색은 무엇일까요?","options":[{"t":"파란색","correct":true},{"t":"빨간색","mis":"M2-1-u5-X10"},{"t":"노란색","mis":"M2-1-u5-X10"}],"explanation":["빨간색 6, 노란색 3, 파란색 4, 흰색 2예요.","가장 많은 것은 빨간색, 그다음은 파란색이에요.","수를 큰 것부터 차례로 견주어요."],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","노란색","파란색","흰색"],"counts":[6,3,4,2],"unit":"조각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_challenge#7','math',2,1,'u5','L05','g2_1_math_u5_L05_challenge','lesson_challenge','M2-1-u5-C5',3,'mc','auto','과일을 종류에 따라 세었어요. 가장 많은 과일은 가장 적은 과일보다 몇 개 더 많을까요?',ARRAY['M2-1-u5-X11','M2-1-u5-X10']::text[],false,'{"seq":7,"concept":"M2-1-u5-C5","difficulty":3,"kind":"mc","stem":"과일을 종류에 따라 세었어요. 가장 많은 과일은 가장 적은 과일보다 몇 개 더 많을까요?","options":[{"t":"5개","correct":true},{"t":"13개","mis":"M2-1-u5-X11"},{"t":"2개","mis":"M2-1-u5-X10"}],"explanation":["가장 많은 것은 포도 9개, 가장 적은 것은 귤 4개예요.","9 − 4 = 5이니 5개 더 많아요.","가장 많은 것과 가장 적은 것을 먼저 찾아요."],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","포도","딸기"],"counts":[7,4,9,5],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_challenge#8','math',2,1,'u5','L05','g2_1_math_u5_L05_challenge','lesson_challenge','M2-1-u5-C5',4,'mc','auto','분리배출한 물건을 종류에 따라 세었어요. 수거함 하나가 넘쳐서 같은 수거함을 하나 더 놓으려고 해요. 어떤 수거함을 더 놓으면 좋을까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],false,'{"seq":8,"concept":"M2-1-u5-C5","difficulty":4,"kind":"mc","stem":"분리배출한 물건을 종류에 따라 세었어요. 수거함 하나가 넘쳐서 같은 수거함을 하나 더 놓으려고 해요. 어떤 수거함을 더 놓으면 좋을까요?","options":[{"t":"플라스틱 수거함","correct":true},{"t":"캔 수거함","mis":"M2-1-u5-X12"},{"t":"종이 수거함","mis":"M2-1-u5-X10"}],"explanation":["캔 5개, 플라스틱 8개, 종이 6개예요.","플라스틱이 가장 많아서 수거함이 먼저 넘쳐요.","분류한 결과를 보고 필요한 것을 정할 수 있어요."],"asset":{"type":"sort_table","crit":"kind","cols":["캔","플라스틱","종이"],"counts":[5,8,6],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_challenge#9','math',2,1,'u5','L05','g2_1_math_u5_L05_challenge','lesson_challenge','M2-1-u5-C5',4,'essay','teacher','표를 보고 알 수 있는 것을 세 가지 써 보세요. (가장 많은 것, 가장 적은 것, 전체 수 등)','{}'::text[],false,'{"seq":9,"concept":"M2-1-u5-C5","difficulty":4,"kind":"essay","stem":"표를 보고 알 수 있는 것을 세 가지 써 보세요. (가장 많은 것, 가장 적은 것, 전체 수 등)","answer_guide":{"answer":"예: 플라스틱이 8개로 가장 많다. 캔이 5개로 가장 적다. 분리배출한 물건은 모두 19개이다.","scoring_points":["가장 많은 것을 수와 함께 썼는가","가장 적은 것을 수와 함께 썼는가","전체 수(5 + 8 + 6 = 19)나 차이를 바르게 썼는가"]},"explanation":["수를 견주어 많고 적음을 찾아요.","모두 더하면 전체 수예요.","표에 있는 것만 말해요."],"asset":{"type":"sort_table","crit":"kind","cols":["캔","플라스틱","종이"],"counts":[5,8,6],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_L05_challenge#10','math',2,1,'u5','L05','g2_1_math_u5_L05_challenge','lesson_challenge','M2-1-u5-C5',4,'essay','teacher','단추 10개를 색깔에 따라 나누어 세면 빨간색 6개, 파란색 4개예요. 같은 단추를 모양에 따라 나누면 동그라미가 7개예요. 네모는 몇 개일지 구하고, 그렇게 생각한 까닭을 써 보세요. (단추는 동그라미와 네모뿐이에요.)','{}'::text[],false,'{"seq":10,"concept":"M2-1-u5-C5","difficulty":4,"kind":"essay","stem":"단추 10개를 색깔에 따라 나누어 세면 빨간색 6개, 파란색 4개예요. 같은 단추를 모양에 따라 나누면 동그라미가 7개예요. 네모는 몇 개일지 구하고, 그렇게 생각한 까닭을 써 보세요. (단추는 동그라미와 네모뿐이에요.)","answer_guide":{"answer":"예: 네모는 3개이다. 기준을 바꾸어 나누어도 단추는 모두 10개 그대로이므로 10에서 동그라미 7개를 빼면 3개이다.","scoring_points":["네모 3개라고 답했는가","기준이 달라도 전체 수는 10개로 같다고 썼는가","10 − 7 = 3으로 구했는가"]},"explanation":["기준이 달라도 전체 수는 같아요.","10 − 7 = 3이에요.","네모는 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#1','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C1',1,'mc','auto','장난감이 방바닥에 흩어져 있어요. 알맞게 정리하는 방법은 어느 것인가요?',ARRAY['M2-1-u5-X01']::text[],false,'{"seq":1,"concept":"M2-1-u5-C1","difficulty":1,"kind":"mc","stem":"장난감이 방바닥에 흩어져 있어요. 알맞게 정리하는 방법은 어느 것인가요?","options":[{"t":"인형은 인형끼리, 블록은 블록끼리 모아요","correct":true},{"t":"보이는 상자에 모두 섞어 넣어요","mis":"M2-1-u5-X01"},{"t":"침대 밑에 밀어 넣어요","mis":"M2-1-u5-X01"}],"explanation":["같은 종류끼리 모아 담아요.","같은 것끼리 모으면 찾기 쉬워요.","아무 데나 두면 다시 찾기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#2','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C2',1,'mc','auto','공을 나눌 때 분명한 기준은 어느 것인가요?',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":2,"concept":"M2-1-u5-C2","difficulty":1,"kind":"mc","stem":"공을 나눌 때 분명한 기준은 어느 것인가요?","options":[{"t":"공의 색깔","correct":true},{"t":"마음에 드는 공","mis":"M2-1-u5-X02"},{"t":"예쁜 공","mis":"M2-1-u5-X02"}],"explanation":["공의 색깔은 누가 보아도 같아요.","마음에 드는 공, 예쁜 공은 사람마다 달라요.","누가 나누어도 같은 기준이 분명한 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#3','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C2',1,'ox','auto','「맛있는 음식과 맛없는 음식」은 분명한 기준이에요.',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":3,"concept":"M2-1-u5-C2","difficulty":1,"kind":"ox","stem":"「맛있는 음식과 맛없는 음식」은 분명한 기준이에요.","answer":"X","reason_options":[{"t":"사람마다 맛있다고 느끼는 것이 다르니까","correct":true},{"t":"내 입맛은 내가 잘 아니까","mis":"M2-1-u5-X02"}],"mis":"M2-1-u5-X02","explanation":["맛있는지는 사람마다 달라요.","결과가 사람마다 달라져요.","「누가 나누어도 같을까?」를 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#4','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C3',1,'mc','auto','동물을 다리 수에 따라 나눌 때 🐧 펭귄이 들어갈 칸은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":4,"concept":"M2-1-u5-C3","difficulty":1,"kind":"mc","stem":"동물을 다리 수에 따라 나눌 때 🐧 펭귄이 들어갈 칸은 어느 것인가요?","options":[{"t":"다리 2개","correct":true},{"t":"다리 4개","mis":"M2-1-u5-X05"},{"t":"다리 0개","mis":"M2-1-u5-X05"}],"explanation":["펭귄은 다리가 2개예요.","그래서 「다리 2개」 칸에 넣어요.","기준만 보고 칸을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#5','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C4',1,'mc','auto','귤은 몇 개일까요?',ARRAY['M2-1-u5-X06']::text[],true,'{"seq":5,"concept":"M2-1-u5-C4","difficulty":1,"kind":"mc","stem":"귤은 몇 개일까요?","explanation":["귤만 골라 하나씩 ／ 표시를 하며 세어요.","귤은 4개예요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"cls":{"ask":"count","fams":["fruit","ani","veh","tok"]}},"options":[{"t":"4개","correct":true},{"t":"5개","mis":"M2-1-u5-X06"},{"t":"3개","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_pile","items":["🍎","🍊","🍎","🍎","🍌","🍊","🍊","🍊","🍌"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#6','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C4',1,'mc','auto','／ 표시를 보고 수를 읽으세요. 「／／／／／ ／／／」는 몇일까요?',ARRAY['M2-1-u5-X13']::text[],false,'{"seq":6,"concept":"M2-1-u5-C4","difficulty":1,"kind":"mc","stem":"／ 표시를 보고 수를 읽으세요. 「／／／／／ ／／／」는 몇일까요?","options":[{"t":"8","correct":true},{"t":"3","mis":"M2-1-u5-X13"},{"t":"7","mis":"M2-1-u5-X13"}],"explanation":["／ 다섯 개가 한 묶음이에요.","5와 3을 이어 세면 8이에요.","묶음 하나는 5로 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#7','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C5',1,'mc','auto','종류에 따라 분류했을 때 가장 많은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":7,"concept":"M2-1-u5-C5","difficulty":1,"kind":"mc","stem":"종류에 따라 분류했을 때 가장 많은 것은 무엇일까요?","explanation":["종류에 따라 세면 사과 4개, 귤 6개, 바나나 3개예요.","수가 가장 큰 칸은 귤(6개)이에요.","「가장 많은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"most","src":"table","fams":["fruit","tok","book","recy"]}},"options":[{"t":"귤","correct":true},{"t":"바나나","mis":"M2-1-u5-X12"},{"t":"사과","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","바나나"],"counts":[4,6,3],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#8','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C5',1,'mc','auto','다리 수에 따라 분류했을 때 가장 적은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":8,"concept":"M2-1-u5-C5","difficulty":1,"kind":"mc","stem":"다리 수에 따라 분류했을 때 가장 적은 것은 무엇일까요?","explanation":["다리 수에 따라 세면 다리 0개 4마리, 다리 2개 2마리, 다리 4개 5마리예요.","수가 가장 작은 칸은 다리 2개(2마리)예요.","「가장 적은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"least","fams":["fruit","ani","tok","veh"]}},"options":[{"t":"다리 2개","correct":true},{"t":"다리 4개","mis":"M2-1-u5-X12"},{"t":"다리 0개","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_pile","items":["🐦","🦆","🐬","🐍","🐮","🐷","🐶","🐮","🐍","🐷","🐍"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#9','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C2',2,'mc','auto','옷을 나누는 기준 가운데 분명한 기준이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u5-X12']::text[],false,'{"seq":9,"concept":"M2-1-u5-C2","difficulty":2,"kind":"mc","stem":"옷을 나누는 기준 가운데 분명한 기준이 아닌 것은 어느 것인가요?","options":[{"t":"예쁜 옷","correct":true},{"t":"윗옷과 아래옷","mis":"M2-1-u5-X12"},{"t":"옷의 색깔","mis":"M2-1-u5-X12"}],"explanation":["예쁜 옷은 사람마다 생각이 달라요.","윗옷과 아래옷, 옷의 색깔은 누가 보아도 같아요.","「아닌 것」을 묻는지 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#10','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C3',2,'mc','auto','다리 수에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],true,'{"seq":10,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"다리 수에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?","explanation":["돌고래는 다리가 0개인 동물이에요.","그래서 「다리 0개」 칸에 있어야 하는데 「다리 2개」 칸에 들어가 있어요.","칸의 이름과 물건의 특징을 하나씩 맞춰 봐요."],"variant_rule":{"cls":{"ask":"odd","fams":["ani","veh","tok","recy","cloth"]}},"options":[{"t":"🐬 돌고래","correct":true},{"t":"🐷 돼지","mis":"M2-1-u5-X05"},{"t":"🐮 소","mis":"M2-1-u5-X05"}],"asset":{"type":"sort_bins","crit":"legs","bins":[{"label":"다리 0개","items":["🐟","🐟"]},{"label":"다리 2개","items":["🐬","🐧","🐔","🐔"]},{"label":"다리 4개","items":["🐷","🐱","🐮"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#11','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C3',2,'mc','auto','그림의 단추를 모양에 따라 분류하면 몇 가지로 나눌 수 있을까요?',ARRAY['M2-1-u5-X08','M2-1-u5-X03']::text[],true,'{"seq":11,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"그림의 단추를 모양에 따라 분류하면 몇 가지로 나눌 수 있을까요?","explanation":["모양을 살펴보면 동그라미, 네모, 하트가 있어요.","그래서 3가지로 나눌 수 있어요.","물건의 수(8개)가 아니라 칸이 몇 가지인지 세어요."],"variant_rule":{"cls":{"ask":"groups","fams":["tok","ani","veh","fruit"]}},"options":[{"t":"3가지","correct":true},{"t":"8가지","mis":"M2-1-u5-X08"},{"t":"4가지","mis":"M2-1-u5-X03"}],"asset":{"type":"sort_pile","items":["🟨","🟩","💙","💙","🟨","🟡","🔵","🔵"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#12','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C4',2,'sa','auto','그림의 단추는 모두 몇 개일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M2-1-u5-C4","difficulty":2,"kind":"sa","stem":"그림의 단추는 모두 몇 개일까요? 숫자로 쓰세요.","explanation":["색깔에 따라 나누어 세면 빨간색 4개, 파란색 3개, 노란색 4개예요.","4 + 3 + 4 = 11이니 모두 11개예요.","각 칸의 수를 모두 더하면 전체 수와 같아요."],"variant_rule":{"cls":{"ask":"total","fams":["tok","ani","fruit","veh"]}},"answer":["11","11개"],"asset":{"type":"sort_pile","items":["💙","🟥","🟡","🔵","🟨","💛","💙","🟡","🟥","🔴","🔴"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#13','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C4',2,'sa','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-1-u5-C4","difficulty":2,"kind":"sa","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.","explanation":["「빨간색」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／ → 6","그래서 빈칸은 6이에요."],"variant_rule":{"cls":{"ask":"tally","fams":["tok","recy","fruit","book"]}},"answer":["6"],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","노란색","파란색"],"counts":[null,3,4],"unit":"개","tally":[6,3,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#14','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C5',2,'sa','auto','귤은 바나나보다 몇 개 더 많을까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M2-1-u5-C5","difficulty":2,"kind":"sa","stem":"귤은 바나나보다 몇 개 더 많을까요? 숫자로 쓰세요.","explanation":["귤은 6개, 바나나는 3개예요.","6 − 3 = 3이니 3개 더 많아요.","「더 많은」 수는 두 수의 차이예요. 더하지 않아요."],"variant_rule":{"cls":{"ask":"diff","src":"table","fams":["fruit","ani","book","tok"]}},"answer":["3","3개"],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","바나나"],"counts":[4,6,3],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#15','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C5',2,'mc','auto','과일을 종류에 따라 센 표를 보고 알 수 있는 것은 어느 것인가요?',ARRAY['M2-1-u5-X09']::text[],false,'{"seq":15,"concept":"M2-1-u5-C5","difficulty":2,"kind":"mc","stem":"과일을 종류에 따라 센 표를 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"귤이 사과보다 많다는 것","correct":true},{"t":"과일을 누가 샀는지","mis":"M2-1-u5-X09"},{"t":"과일이 얼마나 단지","mis":"M2-1-u5-X09"}],"explanation":["표에는 칸 이름과 수만 있어요.","귤 6개, 사과 4개이니 귤이 더 많아요.","표에 없는 것은 알 수 없어요."],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","바나나"],"counts":[4,6,3],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#16','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C3',2,'mc','auto','단추를 색깔에 따라 나눌 때 🟨 노란 네모와 같은 칸에 들어갈 단추는 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":16,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"단추를 색깔에 따라 나눌 때 🟨 노란 네모와 같은 칸에 들어갈 단추는 어느 것인가요?","options":[{"t":"💛 노란 하트","correct":true},{"t":"🟦 파란 네모","mis":"M2-1-u5-X05"},{"t":"🟩 초록 네모","mis":"M2-1-u5-X05"}],"explanation":["기준은 색깔이에요.","노란색끼리 한 칸이니 노란 하트예요.","기준이 아닌 특징은 보지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#17','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C3',3,'mc','auto','물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?',ARRAY['M2-1-u5-X05','M2-1-u5-X02']::text[],true,'{"seq":17,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?","explanation":["칸마다 모양이 같아요: 가 동그라미, 나 네모, 다 하트.","색깔은 한 칸 안에서도 서로 달라요.","칸 안의 물건이 모두 같은 특징을 찾으면 그것이 기준이에요."],"variant_rule":{"cls":{"ask":"crit","fams":["tok","veh"],"crits":["color","shape","where"]}},"options":[{"t":"모양","correct":true},{"t":"색깔","mis":"M2-1-u5-X05"},{"t":"좋아하는 것과 싫어하는 것","mis":"M2-1-u5-X02"}],"asset":{"type":"sort_bins","bins":[{"label":"가","items":["🟡","🔴","🟡"]},{"label":"나","items":["🟥","🟩","🟩"]},{"label":"다","items":["❤️","💚","💙"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#18','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C4',3,'mc','auto','표의 빈칸에 알맞은 수는 얼마일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X06']::text[],true,'{"seq":18,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"표의 빈칸에 알맞은 수는 얼마일까요?","explanation":["나머지 칸을 더하면 4 + 6 = 10이에요.","10 + □ = 13이니 □ = 3이에요.","각 칸의 수를 모두 더하면 합계와 같아요."],"variant_rule":{"cls":{"ask":"blank","src":"table","fams":["fruit","sup","ani","recy"]}},"options":[{"t":"3","correct":true},{"t":"13","mis":"M2-1-u5-X07"},{"t":"4","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","바나나"],"counts":[4,6,null],"unit":"개","total":13}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#19','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C3',3,'mc','auto','그림에서 파란색이면서 네모 모양인 단추는 몇 개일까요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":19,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"그림에서 파란색이면서 네모 모양인 단추는 몇 개일까요?","options":[{"t":"2개","correct":true},{"t":"5개","mis":"M2-1-u5-X05"},{"t":"4개","mis":"M2-1-u5-X05"}],"explanation":["파란색 단추는 파란 네모 2개, 파란 동그라미 2개, 파란 하트 1개로 5개예요.","그 가운데 네모 모양은 2개예요.","두 가지 특징을 모두 갖춘 것만 세어요."],"asset":{"type":"sort_pile","items":["🟦","🔵","🟥","💙","🟦","🟨","🔵","🟩"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#20','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C5',3,'error','auto','조각보 조각을 색깔에 따라 세었더니 빨간색 6조각, 노란색 3조각, 파란색 4조각, 흰색 2조각이었어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u5-X12','M2-1-u5-X07','M2-1-u5-X11']::text[],false,'{"seq":20,"concept":"M2-1-u5-C5","difficulty":3,"kind":"error","stem":"조각보 조각을 색깔에 따라 세었더니 빨간색 6조각, 노란색 3조각, 파란색 4조각, 흰색 2조각이었어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「흰색을 가장 많이 썼어.」","correct":true,"mis_target":"M2-1-u5-X12"},{"t":"로아 — 「조각은 모두 15조각이야.」","mis":"M2-1-u5-X07"},{"t":"시우 — 「빨간색이 파란색보다 2조각 더 많아.」","mis":"M2-1-u5-X11"}],"explanation":["흰색은 2조각으로 가장 적게 썼어요.","가장 많이 쓴 색은 빨간색이에요.","나머지 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#21','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C4',3,'mc','auto','단추 11개를 색깔에 따라 나누면 빨간색 6개, 파란색 5개예요. 같은 단추를 모양에 따라 나누면 동그라미가 8개이고 나머지는 네모예요. 네모 단추는 몇 개일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X04']::text[],false,'{"seq":21,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"단추 11개를 색깔에 따라 나누면 빨간색 6개, 파란색 5개예요. 같은 단추를 모양에 따라 나누면 동그라미가 8개이고 나머지는 네모예요. 네모 단추는 몇 개일까요?","options":[{"t":"3개","correct":true},{"t":"11개","mis":"M2-1-u5-X07"},{"t":"5개","mis":"M2-1-u5-X04"}],"explanation":["기준을 바꾸어 나누어도 전체는 11개 그대로예요.","11 − 8 = 3이니 3개예요.","각 칸의 수를 더하면 전체 수와 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#22','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C5',3,'mc','auto','우리 반 친구들이 가져온 과일을 종류에 따라 세었어요. 가장 많은 과일로 꼬치를 만들려고 해요. 어떤 과일을 쓰면 좋을까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],false,'{"seq":22,"concept":"M2-1-u5-C5","difficulty":3,"kind":"mc","stem":"우리 반 친구들이 가져온 과일을 종류에 따라 세었어요. 가장 많은 과일로 꼬치를 만들려고 해요. 어떤 과일을 쓰면 좋을까요?","options":[{"t":"귤","correct":true},{"t":"바나나","mis":"M2-1-u5-X12"},{"t":"사과","mis":"M2-1-u5-X10"}],"explanation":["사과 4개, 귤 6개, 바나나 3개예요.","가장 많은 것은 귤이에요.","분류한 결과로 필요한 것을 정할 수 있어요."],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","바나나"],"counts":[4,6,3],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#23','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C2',4,'essay','teacher','친구가 「맛있는 과일과 맛없는 과일」로 나누자고 했어요. 이 기준의 문제점을 쓰고, 누가 나누어도 결과가 같은 기준으로 고쳐 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-1-u5-C2","difficulty":4,"kind":"essay","stem":"친구가 「맛있는 과일과 맛없는 과일」로 나누자고 했어요. 이 기준의 문제점을 쓰고, 누가 나누어도 결과가 같은 기준으로 고쳐 써 보세요.","answer_guide":{"answer":"예: 맛있는 과일과 맛없는 과일은 사람마다 생각이 달라 누가 나누느냐에 따라 결과가 달라진다. 사과·귤·포도처럼 과일의 종류로 나누면 누가 나누어도 같다.","scoring_points":["사람마다 생각이 달라 결과가 달라진다고 썼는가","분명한 기준을 하나 골랐는가","고친 기준으로 생기는 칸을 예로 들었는가"]},"explanation":["사람마다 다른 기준은 결과가 달라요.","색깔·모양·종류·수는 누가 보아도 같아요.","분명한 기준으로 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#24','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C4',4,'essay','teacher','그림의 단추를 색깔에 따라 분류하여 세는 방법을 쓰고, 센 결과를 「빨간색 ○개, 파란색 ○개, 노란색 ○개」 꼴로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u5-C4","difficulty":4,"kind":"essay","stem":"그림의 단추를 색깔에 따라 분류하여 세는 방법을 쓰고, 센 결과를 「빨간색 ○개, 파란색 ○개, 노란색 ○개」 꼴로 써 보세요.","answer_guide":{"answer":"예: 색깔에 따라 칸을 정하고 하나 셀 때마다 ／ 표시를 하며 센다. 빨간색 4개, 파란색 3개, 노란색 2개. 모두 더하면 9개로 전체 수와 같다.","scoring_points":["색깔에 따라 칸을 정했는가","／ 표시를 하며 빠짐없이 세는 방법을 썼는가","칸마다 수를 바르게 쓰고 합이 전체 수와 같은지 확인했는가"]},"explanation":["기준에 따라 칸을 정해요.","／ 표시를 하며 세요.","칸의 수를 더해 전체 수와 견주어요."],"asset":{"type":"sort_pile","items":["🔴","🟦","💛","🟥","🔵","❤️","🟨","🔴","💙"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_a#25','math',2,1,'u5','','g2_1_math_u5_review_a','unit_review','M2-1-u5-C5',4,'essay','teacher','표를 보고 알 수 있는 것을 세 가지 써 보세요. (가장 많은 것, 가장 적은 것, 전체 수, 몇 개 더 많은지 등)','{}'::text[],false,'{"seq":25,"concept":"M2-1-u5-C5","difficulty":4,"kind":"essay","stem":"표를 보고 알 수 있는 것을 세 가지 써 보세요. (가장 많은 것, 가장 적은 것, 전체 수, 몇 개 더 많은지 등)","answer_guide":{"answer":"예: 귤이 6개로 가장 많다. 바나나가 3개로 가장 적다. 과일은 모두 13개이다.","scoring_points":["가장 많은 것을 수와 함께 썼는가","가장 적은 것을 수와 함께 썼는가","전체 수나 두 칸의 차이를 바르게 구해 썼는가"]},"explanation":["수를 견주어 많고 적음을 찾아요.","모두 더하면 전체 수예요.","표에 있는 것만 말해요."],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","바나나"],"counts":[4,6,3],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#1','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C1',1,'mc','auto','신발장에 신발과 책이 섞여 있어요. 알맞게 정리하는 방법은 어느 것인가요?',ARRAY['M2-1-u5-X01']::text[],false,'{"seq":1,"concept":"M2-1-u5-C1","difficulty":1,"kind":"mc","stem":"신발장에 신발과 책이 섞여 있어요. 알맞게 정리하는 방법은 어느 것인가요?","options":[{"t":"신발은 신발장에, 책은 책꽂이에 모아요","correct":true},{"t":"신발장 빈칸에 책도 그대로 둬요","mis":"M2-1-u5-X01"},{"t":"책을 신발 위에 쌓아요","mis":"M2-1-u5-X01"}],"explanation":["같은 것끼리 제자리에 모아요.","같은 것끼리 모으면 찾기 쉬워요.","아무 데나 두면 다시 찾기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#2','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C2',1,'mc','auto','장난감을 나눌 때 분명한 기준은 어느 것인가요?',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":2,"concept":"M2-1-u5-C2","difficulty":1,"kind":"mc","stem":"장난감을 나눌 때 분명한 기준은 어느 것인가요?","options":[{"t":"장난감의 종류","correct":true},{"t":"재미있는 장난감","mis":"M2-1-u5-X02"},{"t":"갖고 싶은 장난감","mis":"M2-1-u5-X02"}],"explanation":["장난감의 종류는 누가 보아도 같아요.","재미있는 장난감, 갖고 싶은 장난감은 사람마다 달라요.","누가 나누어도 같은 기준이 분명한 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#3','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C2',1,'ox','auto','「모양」은 분명한 기준이에요.',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":3,"concept":"M2-1-u5-C2","difficulty":1,"kind":"ox","stem":"「모양」은 분명한 기준이에요.","answer":"O","reason_options":[{"t":"누가 보아도 동그라미는 동그라미니까","correct":true},{"t":"좋아하는 모양이 사람마다 다르니까","mis":"M2-1-u5-X02"}],"mis":"M2-1-u5-X02","explanation":["모양은 눈으로 보고 똑같이 알 수 있어요.","그래서 결과가 같아요.","「누가 나누어도 같을까?」를 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#4','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C3',1,'mc','auto','탈것을 움직이는 곳에 따라 나눌 때 ✈️ 비행기가 들어갈 칸은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":4,"concept":"M2-1-u5-C3","difficulty":1,"kind":"mc","stem":"탈것을 움직이는 곳에 따라 나눌 때 ✈️ 비행기가 들어갈 칸은 어느 것인가요?","options":[{"t":"하늘","correct":true},{"t":"땅","mis":"M2-1-u5-X05"},{"t":"물","mis":"M2-1-u5-X05"}],"explanation":["비행기는 하늘을 날아요.","그래서 「하늘」 칸에 넣어요.","기준만 보고 칸을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#5','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C4',1,'mc','auto','다리가 4개인 동물은 몇 마리일까요?',ARRAY['M2-1-u5-X06']::text[],true,'{"seq":5,"concept":"M2-1-u5-C4","difficulty":1,"kind":"mc","stem":"다리가 4개인 동물은 몇 마리일까요?","explanation":["다리가 4개인 동물만 골라 하나씩 ／ 표시를 하며 세어요.","다리가 4개인 동물은 3마리예요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"cls":{"ask":"count","fams":["fruit","ani","veh","tok"]}},"options":[{"t":"3마리","correct":true},{"t":"4마리","mis":"M2-1-u5-X06"},{"t":"2마리","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_pile","items":["🐬","🐧","🐍","🦆","🐷","🐦","🐔","🐮","🐷"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#6','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C4',1,'mc','auto','／ 표시를 보고 수를 읽으세요. 「／／／／／ ／」는 몇일까요?',ARRAY['M2-1-u5-X13']::text[],false,'{"seq":6,"concept":"M2-1-u5-C4","difficulty":1,"kind":"mc","stem":"／ 표시를 보고 수를 읽으세요. 「／／／／／ ／」는 몇일까요?","options":[{"t":"6","correct":true},{"t":"1","mis":"M2-1-u5-X13"},{"t":"5","mis":"M2-1-u5-X13"}],"explanation":["／ 다섯 개가 한 묶음이에요.","5와 1을 이어 세면 6이에요.","묶음 하나는 5로 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#7','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C5',1,'mc','auto','색깔에 따라 분류했을 때 가장 많은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":7,"concept":"M2-1-u5-C5","difficulty":1,"kind":"mc","stem":"색깔에 따라 분류했을 때 가장 많은 것은 무엇일까요?","explanation":["색깔에 따라 세면 빨간색 6개, 노란색 3개, 파란색 4개, 초록색 2개예요.","수가 가장 큰 칸은 빨간색(6개)이에요.","「가장 많은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"most","src":"table","fams":["fruit","tok","book","recy"]}},"options":[{"t":"빨간색","correct":true},{"t":"초록색","mis":"M2-1-u5-X12"},{"t":"노란색","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","노란색","파란색","초록색"],"counts":[6,3,4,2],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#8','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C5',1,'mc','auto','종류에 따라 분류했을 때 가장 적은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":8,"concept":"M2-1-u5-C5","difficulty":1,"kind":"mc","stem":"종류에 따라 분류했을 때 가장 적은 것은 무엇일까요?","explanation":["종류에 따라 세면 사과 3개, 포도 5개, 딸기 1개예요.","수가 가장 작은 칸은 딸기(1개)예요.","「가장 적은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"least","fams":["fruit","ani","tok","veh"]}},"options":[{"t":"딸기","correct":true},{"t":"포도","mis":"M2-1-u5-X12"},{"t":"사과","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_pile","items":["🍎","🍓","🍇","🍇","🍎","🍇","🍎","🍇","🍇"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#9','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C2',2,'mc','auto','탈것을 나누는 기준 가운데 분명한 기준이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u5-X12']::text[],false,'{"seq":9,"concept":"M2-1-u5-C2","difficulty":2,"kind":"mc","stem":"탈것을 나누는 기준 가운데 분명한 기준이 아닌 것은 어느 것인가요?","options":[{"t":"빨라 보이는 탈것","correct":true},{"t":"움직이는 곳","mis":"M2-1-u5-X12"},{"t":"바퀴의 수","mis":"M2-1-u5-X12"}],"explanation":["빨라 보이는 탈것은 사람마다 생각이 달라요.","움직이는 곳, 바퀴의 수는 누가 보아도 같아요.","「아닌 것」을 묻는지 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#10','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C3',2,'mc','auto','움직이는 곳에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],true,'{"seq":10,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"움직이는 곳에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?","explanation":["배는 물에서 움직이는 탈것이에요.","그래서 「물」 칸에 있어야 하는데 「하늘」 칸에 들어가 있어요.","칸의 이름과 물건의 특징을 하나씩 맞춰 봐요."],"variant_rule":{"cls":{"ask":"odd","fams":["ani","veh","tok","recy","cloth"]}},"options":[{"t":"🚢 배","correct":true},{"t":"✈️ 비행기","mis":"M2-1-u5-X05"},{"t":"🚁 헬리콥터","mis":"M2-1-u5-X05"}],"asset":{"type":"sort_bins","crit":"where","bins":[{"label":"땅","items":["🚗","🚗","🛵"]},{"label":"하늘","items":["🚢","🚁","✈️","✈️"]},{"label":"물","items":["🚤"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#11','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C3',2,'mc','auto','그림의 동물을 다리 수에 따라 분류하면 몇 가지로 나눌 수 있을까요?',ARRAY['M2-1-u5-X08','M2-1-u5-X03']::text[],true,'{"seq":11,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"그림의 동물을 다리 수에 따라 분류하면 몇 가지로 나눌 수 있을까요?","explanation":["다리 수를 살펴보면 다리 2개, 다리 4개가 있어요.","그래서 2가지로 나눌 수 있어요.","물건의 수(8마리)가 아니라 칸이 몇 가지인지 세어요."],"variant_rule":{"cls":{"ask":"groups","fams":["tok","ani","veh","fruit"]}},"options":[{"t":"2가지","correct":true},{"t":"8가지","mis":"M2-1-u5-X08"},{"t":"3가지","mis":"M2-1-u5-X03"}],"asset":{"type":"sort_pile","items":["🐷","🐧","🐱","🐱","🐷","🦆","🐦","🐦"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#12','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C4',2,'sa','auto','그림의 동물은 모두 몇 마리일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M2-1-u5-C4","difficulty":2,"kind":"sa","stem":"그림의 동물은 모두 몇 마리일까요? 숫자로 쓰세요.","explanation":["다리 수에 따라 나누어 세면 다리 0개 3마리, 다리 2개 4마리, 다리 4개 5마리예요.","3 + 4 + 5 = 12이니 모두 12마리예요.","각 칸의 수를 모두 더하면 전체 수와 같아요."],"variant_rule":{"cls":{"ask":"total","fams":["tok","ani","fruit","veh"]}},"answer":["12","12마리"],"asset":{"type":"sort_pile","items":["🐶","🐮","🐔","🐱","🐍","🐧","🐟","🐧","🐶","🐱","🐍","🐔"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#13','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C4',2,'sa','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-1-u5-C4","difficulty":2,"kind":"sa","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.","explanation":["「플라스틱」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／／ → 7","그래서 빈칸은 7이에요."],"variant_rule":{"cls":{"ask":"tally","fams":["tok","recy","fruit","book"]}},"answer":["7"],"asset":{"type":"sort_table","crit":"kind","cols":["캔","플라스틱","종이"],"counts":[5,null,4],"unit":"개","tally":[5,7,4]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#14','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C5',2,'sa','auto','다리가 2개인 동물은 다리가 4개인 동물보다 몇 마리 더 많을까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M2-1-u5-C5","difficulty":2,"kind":"sa","stem":"다리가 2개인 동물은 다리가 4개인 동물보다 몇 마리 더 많을까요? 숫자로 쓰세요.","explanation":["다리가 2개인 동물은 7마리, 다리가 4개인 동물은 4마리예요.","7 − 4 = 3이니 3마리 더 많아요.","「더 많은」 수는 두 수의 차이예요. 더하지 않아요."],"variant_rule":{"cls":{"ask":"diff","src":"table","fams":["fruit","ani","book","tok"]}},"answer":["3","3마리"],"asset":{"type":"sort_table","crit":"legs","cols":["다리 0개","다리 2개","다리 4개"],"counts":[2,7,4],"unit":"마리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#15','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C5',2,'mc','auto','조각보 조각을 색깔에 따라 센 표를 보고 알 수 있는 것은 어느 것인가요?',ARRAY['M2-1-u5-X09']::text[],false,'{"seq":15,"concept":"M2-1-u5-C5","difficulty":2,"kind":"mc","stem":"조각보 조각을 색깔에 따라 센 표를 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"조각이 모두 몇 개인지","correct":true},{"t":"조각보를 누가 만들었는지","mis":"M2-1-u5-X09"},{"t":"조각보를 언제 만들었는지","mis":"M2-1-u5-X09"}],"explanation":["표에는 칸 이름과 수만 있어요.","6 + 3 + 4 + 2 = 15조각이에요.","표에 없는 것은 알 수 없어요."],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","노란색","파란색","흰색"],"counts":[6,3,4,2],"unit":"조각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#16','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C3',2,'mc','auto','단추를 모양에 따라 나눌 때 💙 파란 하트와 같은 칸에 들어갈 단추는 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":16,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"단추를 모양에 따라 나눌 때 💙 파란 하트와 같은 칸에 들어갈 단추는 어느 것인가요?","options":[{"t":"❤️ 빨간 하트","correct":true},{"t":"🔵 파란 동그라미","mis":"M2-1-u5-X05"},{"t":"🟦 파란 네모","mis":"M2-1-u5-X05"}],"explanation":["기준은 모양이에요.","하트끼리 한 칸이니 빨간 하트예요.","기준이 아닌 특징은 보지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#17','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C3',3,'mc','auto','물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?',ARRAY['M2-1-u5-X05','M2-1-u5-X02']::text[],true,'{"seq":17,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?","explanation":["칸마다 움직이는 곳이 같아요: 가 땅, 나 하늘, 다 물.","바퀴 수는 한 칸 안에서도 서로 달라요.","칸 안의 물건이 모두 같은 특징을 찾으면 그것이 기준이에요."],"variant_rule":{"cls":{"ask":"crit","fams":["tok","veh"],"crits":["color","shape","where"]}},"options":[{"t":"움직이는 곳","correct":true},{"t":"바퀴 수","mis":"M2-1-u5-X05"},{"t":"멋진 것과 멋지지 않은 것","mis":"M2-1-u5-X02"}],"asset":{"type":"sort_bins","bins":[{"label":"가","items":["🚲","🚗","🚲"]},{"label":"나","items":["✈️","🚁"]},{"label":"다","items":["🚤","⛵","🚤"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#18','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C4',3,'mc','auto','표의 빈칸에 알맞은 수는 얼마일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X06']::text[],true,'{"seq":18,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"표의 빈칸에 알맞은 수는 얼마일까요?","explanation":["나머지 칸을 더하면 2 + 4 + 3 = 9예요.","9 + □ = 14이니 □ = 5예요.","각 칸의 수를 모두 더하면 합계와 같아요."],"variant_rule":{"cls":{"ask":"blank","src":"table","fams":["fruit","sup","ani","recy"]}},"options":[{"t":"5","correct":true},{"t":"14","mis":"M2-1-u5-X07"},{"t":"6","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_table","crit":"kind","cols":["연필","자","공책","가위"],"counts":[null,2,4,3],"unit":"개","total":14}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#19','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C3',3,'mc','auto','그림에서 노란색이면서 하트 모양인 단추는 몇 개일까요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":19,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"그림에서 노란색이면서 하트 모양인 단추는 몇 개일까요?","options":[{"t":"3개","correct":true},{"t":"5개","mis":"M2-1-u5-X05"},{"t":"4개","mis":"M2-1-u5-X05"}],"explanation":["노란색 단추는 노란 하트 3개, 노란 동그라미 2개로 5개예요.","그 가운데 하트 모양은 3개예요.","두 가지 특징을 모두 갖춘 것만 세어요."],"asset":{"type":"sort_pile","items":["💛","🟡","❤️","💛","🟡","💚","💛","💙"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#20','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C5',3,'error','auto','책을 종류에 따라 세었더니 동화책 9권, 위인전 5권, 과학책 6권이었어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u5-X12','M2-1-u5-X07','M2-1-u5-X11']::text[],false,'{"seq":20,"concept":"M2-1-u5-C5","difficulty":3,"kind":"error","stem":"책을 종류에 따라 세었더니 동화책 9권, 위인전 5권, 과학책 6권이었어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「위인전이 가장 많아.」","correct":true,"mis_target":"M2-1-u5-X12"},{"t":"지안 — 「책은 모두 20권이야.」","mis":"M2-1-u5-X07"},{"t":"태민 — 「동화책이 과학책보다 3권 더 많아.」","mis":"M2-1-u5-X11"}],"explanation":["위인전은 5권으로 가장 적어요.","가장 많은 것은 동화책이에요.","나머지 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#21','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C4',3,'mc','auto','탈것 10대를 움직이는 곳에 따라 나누면 땅 6대, 물 4대예요. 같은 탈것을 색깔에 따라 나누면 빨간색이 3대이고 나머지는 모두 흰색이에요. 흰색 탈것은 몇 대일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X04']::text[],false,'{"seq":21,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"탈것 10대를 움직이는 곳에 따라 나누면 땅 6대, 물 4대예요. 같은 탈것을 색깔에 따라 나누면 빨간색이 3대이고 나머지는 모두 흰색이에요. 흰색 탈것은 몇 대일까요?","options":[{"t":"7대","correct":true},{"t":"10대","mis":"M2-1-u5-X07"},{"t":"4대","mis":"M2-1-u5-X04"}],"explanation":["기준을 바꾸어 나누어도 전체는 10대 그대로예요.","10 − 3 = 7이니 7대예요.","각 칸의 수를 더하면 전체 수와 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#22','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C5',3,'mc','auto','조각보를 하나 더 만들려고 해요. 지난번에 가장 적게 쓴 색을 이번에는 더 많이 쓰려고 해요. 어떤 색을 더 많이 쓰면 좋을까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],false,'{"seq":22,"concept":"M2-1-u5-C5","difficulty":3,"kind":"mc","stem":"조각보를 하나 더 만들려고 해요. 지난번에 가장 적게 쓴 색을 이번에는 더 많이 쓰려고 해요. 어떤 색을 더 많이 쓰면 좋을까요?","options":[{"t":"흰색","correct":true},{"t":"빨간색","mis":"M2-1-u5-X12"},{"t":"파란색","mis":"M2-1-u5-X10"}],"explanation":["빨간색 6, 노란색 3, 파란색 4, 흰색 2조각이에요.","가장 적게 쓴 색은 흰색이에요.","분류한 결과로 필요한 것을 정할 수 있어요."],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","노란색","파란색","흰색"],"counts":[6,3,4,2],"unit":"조각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#23','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C2',4,'essay','teacher','친구가 「멋진 탈것과 멋지지 않은 탈것」으로 나누자고 했어요. 이 기준의 문제점을 쓰고, 누가 나누어도 결과가 같은 기준으로 고쳐 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-1-u5-C2","difficulty":4,"kind":"essay","stem":"친구가 「멋진 탈것과 멋지지 않은 탈것」으로 나누자고 했어요. 이 기준의 문제점을 쓰고, 누가 나누어도 결과가 같은 기준으로 고쳐 써 보세요.","answer_guide":{"answer":"예: 멋진 탈것과 멋지지 않은 탈것은 사람마다 생각이 달라 누가 나누느냐에 따라 결과가 달라진다. 땅·하늘·물처럼 움직이는 곳으로 나누면 누가 나누어도 같다.","scoring_points":["사람마다 생각이 달라 결과가 달라진다고 썼는가","분명한 기준을 하나 골랐는가","고친 기준으로 생기는 칸을 예로 들었는가"]},"explanation":["사람마다 다른 기준은 결과가 달라요.","색깔·모양·종류·수는 누가 보아도 같아요.","분명한 기준으로 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#24','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C4',4,'essay','teacher','그림의 동물을 다리 수에 따라 분류하여 세는 방법을 쓰고, 센 결과를 「다리 0개 ○마리, 다리 2개 ○마리, 다리 4개 ○마리」 꼴로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u5-C4","difficulty":4,"kind":"essay","stem":"그림의 동물을 다리 수에 따라 분류하여 세는 방법을 쓰고, 센 결과를 「다리 0개 ○마리, 다리 2개 ○마리, 다리 4개 ○마리」 꼴로 써 보세요.","answer_guide":{"answer":"예: 다리 수에 따라 칸을 정하고 하나 셀 때마다 ／ 표시를 하며 센다. 다리 0개 2마리, 다리 2개 3마리, 다리 4개 4마리. 모두 더하면 9마리로 전체 수와 같다.","scoring_points":["다리 수에 따라 칸을 정했는가","／ 표시를 하며 빠짐없이 세는 방법을 썼는가","칸마다 수를 바르게 쓰고 합이 전체 수와 같은지 확인했는가"]},"explanation":["기준에 따라 칸을 정해요.","／ 표시를 하며 세요.","칸의 수를 더해 전체 수와 견주어요."],"asset":{"type":"sort_pile","items":["🐶","🐔","🐟","🐱","🦆","🐍","🐷","🐧","🐮"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_b#25','math',2,1,'u5','','g2_1_math_u5_review_b','unit_review','M2-1-u5-C5',4,'essay','teacher','표를 보고 알 수 있는 것을 세 가지 써 보세요. (가장 많은 것, 가장 적은 것, 전체 수, 몇 개 더 많은지 등)','{}'::text[],false,'{"seq":25,"concept":"M2-1-u5-C5","difficulty":4,"kind":"essay","stem":"표를 보고 알 수 있는 것을 세 가지 써 보세요. (가장 많은 것, 가장 적은 것, 전체 수, 몇 개 더 많은지 등)","answer_guide":{"answer":"예: 빨간색을 6조각으로 가장 많이 썼다. 흰색을 2조각으로 가장 적게 썼다. 조각은 모두 15조각이다.","scoring_points":["가장 많은 것을 수와 함께 썼는가","가장 적은 것을 수와 함께 썼는가","전체 수나 두 칸의 차이를 바르게 구해 썼는가"]},"explanation":["수를 견주어 많고 적음을 찾아요.","모두 더하면 전체 수예요.","표에 있는 것만 말해요."],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","노란색","파란색","흰색"],"counts":[6,3,4,2],"unit":"조각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#1','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C1',1,'mc','auto','필통 속 물건이 뒤섞여 있어요. 알맞게 정리하는 방법은 어느 것인가요?',ARRAY['M2-1-u5-X01']::text[],false,'{"seq":1,"concept":"M2-1-u5-C1","difficulty":1,"kind":"mc","stem":"필통 속 물건이 뒤섞여 있어요. 알맞게 정리하는 방법은 어느 것인가요?","options":[{"t":"연필은 연필끼리, 색연필은 색연필끼리 모아요","correct":true},{"t":"손에 잡히는 대로 넣어요","mis":"M2-1-u5-X01"},{"t":"쓰지 않는 것만 꺼내요","mis":"M2-1-u5-X01"}],"explanation":["같은 것끼리 모아 넣어요.","같은 것끼리 모으면 찾기 쉬워요.","아무 데나 두면 다시 찾기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#2','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C2',1,'mc','auto','동물을 나눌 때 분명한 기준은 어느 것인가요?',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":2,"concept":"M2-1-u5-C2","difficulty":1,"kind":"mc","stem":"동물을 나눌 때 분명한 기준은 어느 것인가요?","options":[{"t":"다리의 수","correct":true},{"t":"귀여운 동물","mis":"M2-1-u5-X02"},{"t":"무서운 동물","mis":"M2-1-u5-X02"}],"explanation":["다리의 수는 누가 보아도 같아요.","귀여운 동물, 무서운 동물은 사람마다 달라요.","누가 나누어도 같은 기준이 분명한 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#3','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C2',1,'ox','auto','「멋진 탈것과 멋지지 않은 탈것」은 분명한 기준이에요.',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":3,"concept":"M2-1-u5-C2","difficulty":1,"kind":"ox","stem":"「멋진 탈것과 멋지지 않은 탈것」은 분명한 기준이에요.","answer":"X","reason_options":[{"t":"멋진지는 사람마다 다르게 느끼니까","correct":true},{"t":"멋진 것은 누구나 알아보니까","mis":"M2-1-u5-X02"}],"mis":"M2-1-u5-X02","explanation":["멋진지는 사람마다 달라요.","움직이는 곳으로 나누면 분명해요.","「누가 나누어도 같을까?」를 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#4','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C3',1,'mc','auto','옷을 윗옷과 아래옷으로 나눌 때 🩳 반바지가 들어갈 칸은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":4,"concept":"M2-1-u5-C3","difficulty":1,"kind":"mc","stem":"옷을 윗옷과 아래옷으로 나눌 때 🩳 반바지가 들어갈 칸은 어느 것인가요?","options":[{"t":"아래옷","correct":true},{"t":"윗옷","mis":"M2-1-u5-X05"},{"t":"둘 다","mis":"M2-1-u5-X05"}],"explanation":["반바지는 아래에 입는 옷이에요.","그래서 「아래옷」 칸에 넣어요.","기준만 보고 칸을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#5','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C4',1,'mc','auto','물에서 움직이는 탈것은 몇 대일까요?',ARRAY['M2-1-u5-X06']::text[],true,'{"seq":5,"concept":"M2-1-u5-C4","difficulty":1,"kind":"mc","stem":"물에서 움직이는 탈것은 몇 대일까요?","explanation":["물에서 움직이는 탈것만 골라 하나씩 ／ 표시를 하며 세어요.","물에서 움직이는 탈것은 3대예요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"cls":{"ask":"count","fams":["fruit","ani","veh","tok"]}},"options":[{"t":"3대","correct":true},{"t":"4대","mis":"M2-1-u5-X06"},{"t":"2대","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_pile","items":["🛵","🛵","🚕","🚲","🚢","✈️","✈️","🚤","🚢"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#6','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C4',1,'mc','auto','／ 표시를 보고 수를 읽으세요. 「／／／／／ ／／／／／」는 몇일까요?',ARRAY['M2-1-u5-X13']::text[],false,'{"seq":6,"concept":"M2-1-u5-C4","difficulty":1,"kind":"mc","stem":"／ 표시를 보고 수를 읽으세요. 「／／／／／ ／／／／／」는 몇일까요?","options":[{"t":"10","correct":true},{"t":"2","mis":"M2-1-u5-X13"},{"t":"8","mis":"M2-1-u5-X13"}],"explanation":["／ 다섯 개가 한 묶음이에요.","5가 두 묶음이면 10이에요.","묶음 하나는 5로 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#7','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C5',1,'mc','auto','색깔에 따라 분류했을 때 가장 많은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":7,"concept":"M2-1-u5-C5","difficulty":1,"kind":"mc","stem":"색깔에 따라 분류했을 때 가장 많은 것은 무엇일까요?","explanation":["색깔에 따라 세면 빨간색 7권, 초록색 5권, 파란색 8권이에요.","수가 가장 큰 칸은 파란색(8권)이에요.","「가장 많은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"most","src":"table","fams":["fruit","tok","book","recy"]}},"options":[{"t":"파란색","correct":true},{"t":"초록색","mis":"M2-1-u5-X12"},{"t":"빨간색","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","초록색","파란색"],"counts":[7,5,8],"unit":"권"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#8','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C5',1,'mc','auto','움직이는 곳에 따라 분류했을 때 가장 적은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":8,"concept":"M2-1-u5-C5","difficulty":1,"kind":"mc","stem":"움직이는 곳에 따라 분류했을 때 가장 적은 것은 무엇일까요?","explanation":["움직이는 곳에 따라 세면 땅 5대, 하늘 3대, 물 1대예요.","수가 가장 작은 칸은 물(1대)이에요.","「가장 적은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"least","fams":["fruit","ani","tok","veh"]}},"options":[{"t":"물","correct":true},{"t":"땅","mis":"M2-1-u5-X12"},{"t":"하늘","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_pile","items":["🚲","🚤","✈️","🚕","🛵","🚁","🚲","✈️","🚕"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#9','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C2',2,'mc','auto','학용품을 나누는 기준 가운데 분명한 기준이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u5-X12']::text[],false,'{"seq":9,"concept":"M2-1-u5-C2","difficulty":2,"kind":"mc","stem":"학용품을 나누는 기준 가운데 분명한 기준이 아닌 것은 어느 것인가요?","options":[{"t":"갖고 싶은 학용품","correct":true},{"t":"학용품의 종류","mis":"M2-1-u5-X12"},{"t":"학용품의 색깔","mis":"M2-1-u5-X12"}],"explanation":["갖고 싶은 학용품은 사람마다 생각이 달라요.","학용품의 종류, 학용품의 색깔은 누가 보아도 같아요.","「아닌 것」을 묻는지 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#10','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C3',2,'mc','auto','색깔에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],true,'{"seq":10,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"색깔에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?","explanation":["파란 동그라미는 파란색인 것이에요.","그래서 「파란색」 칸에 있어야 하는데 「초록색」 칸에 들어가 있어요.","칸의 이름과 물건의 특징을 하나씩 맞춰 봐요."],"variant_rule":{"cls":{"ask":"odd","fams":["ani","veh","tok","recy","cloth"]}},"options":[{"t":"🔵 파란 동그라미","correct":true},{"t":"🟩 초록 네모","mis":"M2-1-u5-X05"},{"t":"💙 파란 하트","mis":"M2-1-u5-X05"}],"asset":{"type":"sort_bins","crit":"color","bins":[{"label":"빨간색","items":["🔴","🔴","❤️"]},{"label":"파란색","items":["💙","🔵"]},{"label":"초록색","items":["🔵","💚","🟩","💚"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#11','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C3',2,'mc','auto','그림의 과일을 종류에 따라 분류하면 몇 가지로 나눌 수 있을까요?',ARRAY['M2-1-u5-X08','M2-1-u5-X03']::text[],true,'{"seq":11,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"그림의 과일을 종류에 따라 분류하면 몇 가지로 나눌 수 있을까요?","explanation":["종류를 살펴보면 사과, 바나나, 포도, 귤이 있어요.","그래서 4가지로 나눌 수 있어요.","물건의 수(9개)가 아니라 칸이 몇 가지인지 세어요."],"variant_rule":{"cls":{"ask":"groups","fams":["tok","ani","veh","fruit"]}},"options":[{"t":"4가지","correct":true},{"t":"9가지","mis":"M2-1-u5-X08"},{"t":"5가지","mis":"M2-1-u5-X03"}],"asset":{"type":"sort_pile","items":["🍇","🍊","🍌","🍎","🍊","🍎","🍇","🍌","🍌"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#12','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C4',2,'sa','auto','그림의 과일은 모두 몇 개일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M2-1-u5-C4","difficulty":2,"kind":"sa","stem":"그림의 과일은 모두 몇 개일까요? 숫자로 쓰세요.","explanation":["종류에 따라 나누어 세면 사과 5개, 귤 3개, 포도 4개예요.","5 + 3 + 4 = 12이니 모두 12개예요.","각 칸의 수를 모두 더하면 전체 수와 같아요."],"variant_rule":{"cls":{"ask":"total","fams":["tok","ani","fruit","veh"]}},"answer":["12","12개"],"asset":{"type":"sort_pile","items":["🍇","🍇","🍊","🍇","🍎","🍊","🍎","🍎","🍊","🍇","🍎","🍎"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#13','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C4',2,'sa','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-1-u5-C4","difficulty":2,"kind":"sa","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.","explanation":["「사과」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／／／ → 8","그래서 빈칸은 8이에요."],"variant_rule":{"cls":{"ask":"tally","fams":["tok","recy","fruit","book"]}},"answer":["8"],"asset":{"type":"sort_table","crit":"kind","cols":["사과","귤","바나나"],"counts":[null,5,3],"unit":"개","tally":[8,5,3]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#14','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C5',2,'sa','auto','빨간색인 책은 초록색인 책보다 몇 권 더 많을까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M2-1-u5-C5","difficulty":2,"kind":"sa","stem":"빨간색인 책은 초록색인 책보다 몇 권 더 많을까요? 숫자로 쓰세요.","explanation":["빨간색인 책은 8권, 초록색인 책은 3권이에요.","8 − 3 = 5이니 5권 더 많아요.","「더 많은」 수는 두 수의 차이예요. 더하지 않아요."],"variant_rule":{"cls":{"ask":"diff","src":"table","fams":["fruit","ani","book","tok"]}},"answer":["5","5권"],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","초록색","파란색"],"counts":[8,3,5],"unit":"권"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#15','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C5',2,'mc','auto','책을 종류에 따라 센 표를 보고 알 수 있는 것은 어느 것인가요?',ARRAY['M2-1-u5-X09']::text[],false,'{"seq":15,"concept":"M2-1-u5-C5","difficulty":2,"kind":"mc","stem":"책을 종류에 따라 센 표를 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"가장 적은 종류의 책","correct":true},{"t":"책을 누가 가장 많이 읽었는지","mis":"M2-1-u5-X09"},{"t":"책이 얼마나 재미있는지","mis":"M2-1-u5-X09"}],"explanation":["표에는 칸 이름과 수만 있어요.","인물 이야기가 5권으로 가장 적어요.","표에 없는 것은 알 수 없어요."],"asset":{"type":"sort_table","crit":"kind","cols":["인물 이야기","그림 동화","신기한 과학"],"counts":[5,9,6],"unit":"권"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#16','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C3',2,'mc','auto','탈것을 움직이는 곳에 따라 나눌 때 🚢 배와 같은 칸에 들어갈 것은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":16,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"탈것을 움직이는 곳에 따라 나눌 때 🚢 배와 같은 칸에 들어갈 것은 어느 것인가요?","options":[{"t":"⛵ 돛단배","correct":true},{"t":"🚌 버스","mis":"M2-1-u5-X05"},{"t":"✈️ 비행기","mis":"M2-1-u5-X05"}],"explanation":["기준은 움직이는 곳이에요.","물에서 움직이는 것끼리 한 칸이니 돛단배예요.","기준이 아닌 특징은 보지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#17','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C3',3,'mc','auto','물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?',ARRAY['M2-1-u5-X05','M2-1-u5-X02']::text[],true,'{"seq":17,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?","explanation":["칸마다 색깔이 같아요: 가 빨간색, 나 초록색, 다 파란색.","모양은 한 칸 안에서도 서로 달라요.","칸 안의 물건이 모두 같은 특징을 찾으면 그것이 기준이에요."],"variant_rule":{"cls":{"ask":"crit","fams":["tok","veh"],"crits":["color","shape","where"]}},"options":[{"t":"색깔","correct":true},{"t":"모양","mis":"M2-1-u5-X05"},{"t":"예쁜 것과 안 예쁜 것","mis":"M2-1-u5-X02"}],"asset":{"type":"sort_bins","bins":[{"label":"가","items":["🟥","🔴","🟥"]},{"label":"나","items":["🟢","💚","💚"]},{"label":"다","items":["🔵","💙"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#18','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C4',3,'mc','auto','표의 빈칸에 알맞은 수는 얼마일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X06']::text[],true,'{"seq":18,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"표의 빈칸에 알맞은 수는 얼마일까요?","explanation":["나머지 칸을 더하면 3 + 5 = 8이에요.","8 + □ = 14이니 □ = 6이에요.","각 칸의 수를 모두 더하면 합계와 같아요."],"variant_rule":{"cls":{"ask":"blank","src":"table","fams":["fruit","sup","ani","recy"]}},"options":[{"t":"6","correct":true},{"t":"14","mis":"M2-1-u5-X07"},{"t":"7","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_table","crit":"legs","cols":["다리 0개","다리 2개","다리 4개"],"counts":[3,null,5],"unit":"마리","total":14}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#19','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C3',3,'mc','auto','그림에서 땅에서 움직이면서 바퀴가 2개인 탈것은 몇 대일까요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":19,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"그림에서 땅에서 움직이면서 바퀴가 2개인 탈것은 몇 대일까요?","options":[{"t":"3대","correct":true},{"t":"6대","mis":"M2-1-u5-X05"},{"t":"5대","mis":"M2-1-u5-X05"}],"explanation":["땅에서 움직이는 탈것은 자전거 2대, 오토바이 1대, 자동차 2대, 버스 1대로 6대예요.","그 가운데 바퀴가 2개인 것은 자전거와 오토바이 3대예요.","두 가지 특징을 모두 갖춘 것만 세어요."],"asset":{"type":"sort_pile","items":["🚲","🚗","✈️","🛵","🚌","⛵","🚲","🚗"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#20','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C5',3,'error','auto','동물을 다리 수에 따라 세었더니 다리 0개 2마리, 다리 2개 7마리, 다리 4개 4마리였어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u5-X12','M2-1-u5-X07','M2-1-u5-X11']::text[],false,'{"seq":20,"concept":"M2-1-u5-C5","difficulty":3,"kind":"error","stem":"동물을 다리 수에 따라 세었더니 다리 0개 2마리, 다리 2개 7마리, 다리 4개 4마리였어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민호 — 「다리가 0개인 동물이 가장 많아.」","correct":true,"mis_target":"M2-1-u5-X12"},{"t":"소율 — 「동물은 모두 13마리야.」","mis":"M2-1-u5-X07"},{"t":"준우 — 「다리 2개인 동물이 다리 4개인 동물보다 3마리 더 많아.」","mis":"M2-1-u5-X11"}],"explanation":["다리가 0개인 동물은 2마리로 가장 적어요.","가장 많은 것은 다리 2개인 동물이에요.","나머지 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#21','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C4',3,'mc','auto','옷 9벌을 윗옷과 아래옷으로 나누면 윗옷 5벌, 아래옷 4벌이에요. 같은 옷을 색깔에 따라 나누면 흰색이 6벌이고 나머지는 모두 검은색이에요. 검은색 옷은 몇 벌일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X04']::text[],false,'{"seq":21,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"옷 9벌을 윗옷과 아래옷으로 나누면 윗옷 5벌, 아래옷 4벌이에요. 같은 옷을 색깔에 따라 나누면 흰색이 6벌이고 나머지는 모두 검은색이에요. 검은색 옷은 몇 벌일까요?","options":[{"t":"3벌","correct":true},{"t":"9벌","mis":"M2-1-u5-X07"},{"t":"4벌","mis":"M2-1-u5-X04"}],"explanation":["기준을 바꾸어 나누어도 전체는 9벌 그대로예요.","9 − 6 = 3이니 3벌이에요.","각 칸의 수를 더하면 전체 수와 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#22','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C5',3,'mc','auto','학급 문고에서 가장 많은 종류의 책을 가장 넓은 칸에 꽂으려고 해요. 어떤 책을 넓은 칸에 꽂으면 좋을까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],false,'{"seq":22,"concept":"M2-1-u5-C5","difficulty":3,"kind":"mc","stem":"학급 문고에서 가장 많은 종류의 책을 가장 넓은 칸에 꽂으려고 해요. 어떤 책을 넓은 칸에 꽂으면 좋을까요?","options":[{"t":"그림 동화","correct":true},{"t":"인물 이야기","mis":"M2-1-u5-X12"},{"t":"신기한 과학","mis":"M2-1-u5-X10"}],"explanation":["인물 이야기 5권, 그림 동화 9권, 신기한 과학 6권이에요.","가장 많은 것은 그림 동화예요.","분류한 결과로 필요한 것을 정할 수 있어요."],"asset":{"type":"sort_table","crit":"kind","cols":["인물 이야기","그림 동화","신기한 과학"],"counts":[5,9,6],"unit":"권"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#23','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C2',4,'essay','teacher','친구가 「귀여운 동물과 안 귀여운 동물」로 나누자고 했어요. 이 기준의 문제점을 쓰고, 누가 나누어도 결과가 같은 기준으로 고쳐 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-1-u5-C2","difficulty":4,"kind":"essay","stem":"친구가 「귀여운 동물과 안 귀여운 동물」로 나누자고 했어요. 이 기준의 문제점을 쓰고, 누가 나누어도 결과가 같은 기준으로 고쳐 써 보세요.","answer_guide":{"answer":"예: 귀여운 동물과 안 귀여운 동물은 사람마다 생각이 달라 누가 나누느냐에 따라 결과가 달라진다. 다리 0개·2개·4개처럼 다리의 수로 나누면 누가 나누어도 같다.","scoring_points":["사람마다 생각이 달라 결과가 달라진다고 썼는가","분명한 기준을 하나 골랐는가","고친 기준으로 생기는 칸을 예로 들었는가"]},"explanation":["사람마다 다른 기준은 결과가 달라요.","색깔·모양·종류·수는 누가 보아도 같아요.","분명한 기준으로 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#24','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C4',4,'essay','teacher','그림의 탈것을 움직이는 곳에 따라 분류하여 세는 방법을 쓰고, 센 결과를 「땅 ○대, 하늘 ○대, 물 ○대」 꼴로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u5-C4","difficulty":4,"kind":"essay","stem":"그림의 탈것을 움직이는 곳에 따라 분류하여 세는 방법을 쓰고, 센 결과를 「땅 ○대, 하늘 ○대, 물 ○대」 꼴로 써 보세요.","answer_guide":{"answer":"예: 움직이는 곳에 따라 칸을 정하고 하나 셀 때마다 ／ 표시를 하며 센다. 땅 4대, 하늘 2대, 물 3대. 모두 더하면 9대로 전체 수와 같다.","scoring_points":["움직이는 곳에 따라 칸을 정했는가","／ 표시를 하며 빠짐없이 세는 방법을 썼는가","칸마다 수를 바르게 쓰고 합이 전체 수와 같은지 확인했는가"]},"explanation":["기준에 따라 칸을 정해요.","／ 표시를 하며 세요.","칸의 수를 더해 전체 수와 견주어요."],"asset":{"type":"sort_pile","items":["🚗","✈️","⛵","🚲","🚢","🚌","🚁","🛵","🚤"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_c#25','math',2,1,'u5','','g2_1_math_u5_review_c','unit_review','M2-1-u5-C5',4,'essay','teacher','표를 보고 알 수 있는 것을 세 가지 써 보세요. (가장 많은 것, 가장 적은 것, 전체 수, 몇 개 더 많은지 등)','{}'::text[],false,'{"seq":25,"concept":"M2-1-u5-C5","difficulty":4,"kind":"essay","stem":"표를 보고 알 수 있는 것을 세 가지 써 보세요. (가장 많은 것, 가장 적은 것, 전체 수, 몇 개 더 많은지 등)","answer_guide":{"answer":"예: 그림 동화가 9권으로 가장 많다. 인물 이야기가 5권으로 가장 적다. 책은 모두 20권이다.","scoring_points":["가장 많은 것을 수와 함께 썼는가","가장 적은 것을 수와 함께 썼는가","전체 수나 두 칸의 차이를 바르게 구해 썼는가"]},"explanation":["수를 견주어 많고 적음을 찾아요.","모두 더하면 전체 수예요.","표에 있는 것만 말해요."],"asset":{"type":"sort_table","crit":"kind","cols":["인물 이야기","그림 동화","신기한 과학"],"counts":[5,9,6],"unit":"권"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#1','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C1',1,'mc','auto','옷장 속 옷이 뒤섞여 있어요. 알맞게 정리하는 방법은 어느 것인가요?',ARRAY['M2-1-u5-X01']::text[],false,'{"seq":1,"concept":"M2-1-u5-C1","difficulty":1,"kind":"mc","stem":"옷장 속 옷이 뒤섞여 있어요. 알맞게 정리하는 방법은 어느 것인가요?","options":[{"t":"윗옷은 윗옷끼리, 아래옷은 아래옷끼리 모아요","correct":true},{"t":"빈 옷걸이에 아무 옷이나 걸어요","mis":"M2-1-u5-X01"},{"t":"옷을 한 칸에 모두 쌓아요","mis":"M2-1-u5-X01"}],"explanation":["같은 것끼리 모아 걸어요.","같은 것끼리 모으면 찾기 쉬워요.","아무 데나 두면 다시 찾기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#2','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C2',1,'mc','auto','책을 나눌 때 분명한 기준은 어느 것인가요?',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":2,"concept":"M2-1-u5-C2","difficulty":1,"kind":"mc","stem":"책을 나눌 때 분명한 기준은 어느 것인가요?","options":[{"t":"책의 색깔","correct":true},{"t":"재미있는 책","mis":"M2-1-u5-X02"},{"t":"읽고 싶은 책","mis":"M2-1-u5-X02"}],"explanation":["책의 색깔은 누가 보아도 같아요.","재미있는 책, 읽고 싶은 책은 사람마다 달라요.","누가 나누어도 같은 기준이 분명한 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#3','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C2',1,'ox','auto','「바퀴의 수」는 분명한 기준이에요.',ARRAY['M2-1-u5-X02']::text[],false,'{"seq":3,"concept":"M2-1-u5-C2","difficulty":1,"kind":"ox","stem":"「바퀴의 수」는 분명한 기준이에요.","answer":"O","reason_options":[{"t":"바퀴는 누가 세어도 같은 수니까","correct":true},{"t":"바퀴가 많은 것을 좋아하는 사람도 있으니까","mis":"M2-1-u5-X02"}],"mis":"M2-1-u5-X02","explanation":["바퀴는 세면 똑같이 나와요.","그래서 결과가 같아요.","「누가 나누어도 같을까?」를 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#4','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C3',1,'mc','auto','분리배출할 물건을 종류에 따라 나눌 때 📰 신문지가 들어갈 칸은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":4,"concept":"M2-1-u5-C3","difficulty":1,"kind":"mc","stem":"분리배출할 물건을 종류에 따라 나눌 때 📰 신문지가 들어갈 칸은 어느 것인가요?","options":[{"t":"종이","correct":true},{"t":"캔","mis":"M2-1-u5-X05"},{"t":"플라스틱","mis":"M2-1-u5-X05"}],"explanation":["신문지는 종이로 만들었어요.","그래서 「종이」 칸에 넣어요.","기준만 보고 칸을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#5','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C4',1,'mc','auto','파란색인 것은 몇 개일까요?',ARRAY['M2-1-u5-X06']::text[],true,'{"seq":5,"concept":"M2-1-u5-C4","difficulty":1,"kind":"mc","stem":"파란색인 것은 몇 개일까요?","explanation":["파란색인 것만 골라 하나씩 ／ 표시를 하며 세어요.","파란색인 것은 5개예요.","빠뜨리거나 두 번 세지 않게 표시하며 세요."],"variant_rule":{"cls":{"ask":"count","fams":["fruit","ani","veh","tok"]}},"options":[{"t":"5개","correct":true},{"t":"6개","mis":"M2-1-u5-X06"},{"t":"4개","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_pile","items":["❤️","🟥","🟨","💙","❤️","🟦","💙","🔵","💛","🟦"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#6','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C4',1,'mc','auto','／ 표시를 보고 수를 읽으세요. 「／／／／／ ／／／／」는 몇일까요?',ARRAY['M2-1-u5-X13']::text[],false,'{"seq":6,"concept":"M2-1-u5-C4","difficulty":1,"kind":"mc","stem":"／ 표시를 보고 수를 읽으세요. 「／／／／／ ／／／／」는 몇일까요?","options":[{"t":"9","correct":true},{"t":"4","mis":"M2-1-u5-X13"},{"t":"8","mis":"M2-1-u5-X13"}],"explanation":["／ 다섯 개가 한 묶음이에요.","5와 4를 이어 세면 9예요.","묶음 하나는 5로 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#7','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C5',1,'mc','auto','종류에 따라 분류했을 때 가장 많은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":7,"concept":"M2-1-u5-C5","difficulty":1,"kind":"mc","stem":"종류에 따라 분류했을 때 가장 많은 것은 무엇일까요?","explanation":["종류에 따라 세면 캔 5개, 플라스틱 8개, 종이 6개예요.","수가 가장 큰 칸은 플라스틱(8개)이에요.","「가장 많은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"most","src":"table","fams":["fruit","tok","book","recy"]}},"options":[{"t":"플라스틱","correct":true},{"t":"캔","mis":"M2-1-u5-X12"},{"t":"종이","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_table","crit":"kind","cols":["캔","플라스틱","종이"],"counts":[5,8,6],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#8','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C5',1,'mc','auto','모양에 따라 분류했을 때 가장 적은 것은 무엇일까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],true,'{"seq":8,"concept":"M2-1-u5-C5","difficulty":1,"kind":"mc","stem":"모양에 따라 분류했을 때 가장 적은 것은 무엇일까요?","explanation":["모양에 따라 세면 동그라미 2개, 네모 4개, 하트 5개예요.","수가 가장 작은 칸은 동그라미(2개)예요.","「가장 적은」을 묻는지 다시 읽어요."],"variant_rule":{"cls":{"ask":"least","fams":["fruit","ani","tok","veh"]}},"options":[{"t":"동그라미","correct":true},{"t":"하트","mis":"M2-1-u5-X12"},{"t":"네모","mis":"M2-1-u5-X10"}],"asset":{"type":"sort_pile","items":["🟦","🟨","🟢","🟡","💚","💛","❤️","💚","🟨","💛","🟦"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#9','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C2',2,'mc','auto','단추를 나누는 기준 가운데 분명한 기준이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u5-X12']::text[],false,'{"seq":9,"concept":"M2-1-u5-C2","difficulty":2,"kind":"mc","stem":"단추를 나누는 기준 가운데 분명한 기준이 아닌 것은 어느 것인가요?","options":[{"t":"마음에 드는 단추","correct":true},{"t":"단추의 모양","mis":"M2-1-u5-X12"},{"t":"단추의 색깔","mis":"M2-1-u5-X12"}],"explanation":["마음에 드는 단추는 사람마다 생각이 달라요.","단추의 모양, 단추의 색깔은 누가 보아도 같아요.","「아닌 것」을 묻는지 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#10','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C3',2,'mc','auto','윗옷과 아래옷에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],true,'{"seq":10,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"윗옷과 아래옷에 따라 분류했어요. 잘못 분류된 것은 어느 것인가요?","explanation":["블라우스는 윗옷이에요.","그래서 「윗옷」 칸에 있어야 하는데 「아래옷」 칸에 들어가 있어요.","칸의 이름과 물건의 특징을 하나씩 맞춰 봐요."],"variant_rule":{"cls":{"ask":"odd","fams":["ani","veh","tok","recy","cloth"]}},"options":[{"t":"👚 블라우스","correct":true},{"t":"👖 바지","mis":"M2-1-u5-X05"},{"t":"🩳 반바지","mis":"M2-1-u5-X05"}],"asset":{"type":"sort_bins","crit":"part","bins":[{"label":"윗옷","items":["👕","👕","👚"]},{"label":"아래옷","items":["👖","👖","🩳","👚"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#11','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C3',2,'mc','auto','그림의 탈것을 움직이는 곳에 따라 분류하면 몇 가지로 나눌 수 있을까요?',ARRAY['M2-1-u5-X08','M2-1-u5-X03']::text[],true,'{"seq":11,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"그림의 탈것을 움직이는 곳에 따라 분류하면 몇 가지로 나눌 수 있을까요?","explanation":["움직이는 곳을 살펴보면 땅, 물이 있어요.","그래서 2가지로 나눌 수 있어요.","물건의 수(8대)가 아니라 칸이 몇 가지인지 세어요."],"variant_rule":{"cls":{"ask":"groups","fams":["tok","ani","veh","fruit"]}},"options":[{"t":"2가지","correct":true},{"t":"8가지","mis":"M2-1-u5-X08"},{"t":"3가지","mis":"M2-1-u5-X03"}],"asset":{"type":"sort_pile","items":["🚢","🛵","🚢","⛵","🚲","🚲","🚌","🚌"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#12','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C4',2,'sa','auto','그림의 탈것은 모두 몇 대일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M2-1-u5-C4","difficulty":2,"kind":"sa","stem":"그림의 탈것은 모두 몇 대일까요? 숫자로 쓰세요.","explanation":["움직이는 곳에 따라 나누어 세면 땅 6대, 하늘 2대, 물 3대예요.","6 + 2 + 3 = 11이니 모두 11대예요.","각 칸의 수를 모두 더하면 전체 수와 같아요."],"variant_rule":{"cls":{"ask":"total","fams":["tok","ani","fruit","veh"]}},"answer":["11","11대"],"asset":{"type":"sort_pile","items":["🛵","🚕","⛵","✈️","🚢","🚤","🛵","✈️","🚕","🚌","🚗"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#13','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C4',2,'sa','auto','／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-1-u5-C4","difficulty":2,"kind":"sa","stem":"／ 표시를 세어 보세요. 표의 빈칸에 알맞은 수는 얼마일까요? 숫자로 쓰세요.","explanation":["「초록색」 칸의 ／ 표시를 세어요.","다섯 개 묶음 하나는 5예요. ／／／／／ ／／／／ → 9","그래서 빈칸은 9예요."],"variant_rule":{"cls":{"ask":"tally","fams":["tok","recy","fruit","book"]}},"answer":["9"],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","초록색","파란색"],"counts":[4,null,6],"unit":"권","tally":[4,9,6]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#14','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C5',2,'sa','auto','빨간색인 것은 파란색인 것보다 몇 개 더 많을까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M2-1-u5-C5","difficulty":2,"kind":"sa","stem":"빨간색인 것은 파란색인 것보다 몇 개 더 많을까요? 숫자로 쓰세요.","explanation":["빨간색인 것은 6개, 파란색인 것은 4개예요.","6 − 4 = 2이니 2개 더 많아요.","「더 많은」 수는 두 수의 차이예요. 더하지 않아요."],"variant_rule":{"cls":{"ask":"diff","src":"table","fams":["fruit","ani","book","tok"]}},"answer":["2","2개"],"asset":{"type":"sort_table","crit":"color","cols":["빨간색","노란색","파란색"],"counts":[6,3,4],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#15','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C5',2,'mc','auto','분리배출한 물건을 종류에 따라 센 표를 보고 알 수 있는 것은 어느 것인가요?',ARRAY['M2-1-u5-X09']::text[],false,'{"seq":15,"concept":"M2-1-u5-C5","difficulty":2,"kind":"mc","stem":"분리배출한 물건을 종류에 따라 센 표를 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"가장 많이 나온 쓰레기의 종류","correct":true},{"t":"쓰레기를 누가 버렸는지","mis":"M2-1-u5-X09"},{"t":"쓰레기를 언제 버렸는지","mis":"M2-1-u5-X09"}],"explanation":["표에는 칸 이름과 수만 있어요.","플라스틱이 8개로 가장 많아요.","표에 없는 것은 알 수 없어요."],"asset":{"type":"sort_table","crit":"kind","cols":["캔","플라스틱","종이"],"counts":[5,8,6],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#16','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C3',2,'mc','auto','동물을 다리 수에 따라 나눌 때 🐶 강아지와 같은 칸에 들어갈 동물은 어느 것인가요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":16,"concept":"M2-1-u5-C3","difficulty":2,"kind":"mc","stem":"동물을 다리 수에 따라 나눌 때 🐶 강아지와 같은 칸에 들어갈 동물은 어느 것인가요?","options":[{"t":"🐮 소","correct":true},{"t":"🐔 닭","mis":"M2-1-u5-X05"},{"t":"🐍 뱀","mis":"M2-1-u5-X05"}],"explanation":["기준은 다리 수예요.","다리가 4개인 것끼리 한 칸이니 소예요.","기준이 아닌 특징은 보지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#17','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C3',3,'mc','auto','물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?',ARRAY['M2-1-u5-X05','M2-1-u5-X02']::text[],true,'{"seq":17,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"물건을 칸에 나누어 담았어요. 어떤 기준으로 분류했을까요?","explanation":["칸마다 색깔이 같아요: 가 노란색, 나 파란색.","모양은 한 칸 안에서도 서로 달라요.","칸 안의 물건이 모두 같은 특징을 찾으면 그것이 기준이에요."],"variant_rule":{"cls":{"ask":"crit","fams":["tok","veh"],"crits":["color","shape","where"]}},"options":[{"t":"색깔","correct":true},{"t":"모양","mis":"M2-1-u5-X05"},{"t":"예쁜 것과 안 예쁜 것","mis":"M2-1-u5-X02"}],"asset":{"type":"sort_bins","bins":[{"label":"가","items":["🟨","🟡","🟨","🟡"]},{"label":"나","items":["💙","💙","🔵","💙"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#18','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C4',3,'mc','auto','표의 빈칸에 알맞은 수는 얼마일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X06']::text[],true,'{"seq":18,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"표의 빈칸에 알맞은 수는 얼마일까요?","explanation":["나머지 칸을 더하면 5 + 6 = 11이에요.","11 + □ = 19이니 □ = 8이에요.","각 칸의 수를 모두 더하면 합계와 같아요."],"variant_rule":{"cls":{"ask":"blank","src":"table","fams":["fruit","sup","ani","recy"]}},"options":[{"t":"8","correct":true},{"t":"19","mis":"M2-1-u5-X07"},{"t":"9","mis":"M2-1-u5-X06"}],"asset":{"type":"sort_table","crit":"kind","cols":["캔","플라스틱","종이"],"counts":[5,null,6],"unit":"개","total":19}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#19','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C3',3,'mc','auto','그림에서 빨간색이면서 네모 모양인 단추는 몇 개일까요?',ARRAY['M2-1-u5-X05']::text[],false,'{"seq":19,"concept":"M2-1-u5-C3","difficulty":3,"kind":"mc","stem":"그림에서 빨간색이면서 네모 모양인 단추는 몇 개일까요?","options":[{"t":"2개","correct":true},{"t":"6개","mis":"M2-1-u5-X05"},{"t":"4개","mis":"M2-1-u5-X05"}],"explanation":["빨간색 단추는 빨간 네모 2개, 빨간 동그라미 3개, 빨간 하트 1개로 6개예요.","그 가운데 네모 모양은 2개예요.","두 가지 특징을 모두 갖춘 것만 세어요."],"asset":{"type":"sort_pile","items":["🟥","🔴","🔴","🟦","❤️","🟥","🔴","🟨"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#20','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C5',3,'error','auto','분리배출한 물건을 세었더니 캔 5개, 플라스틱 8개, 종이 6개였어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u5-X12','M2-1-u5-X07','M2-1-u5-X11']::text[],false,'{"seq":20,"concept":"M2-1-u5-C5","difficulty":3,"kind":"error","stem":"분리배출한 물건을 세었더니 캔 5개, 플라스틱 8개, 종이 6개였어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「캔이 가장 많아.」","correct":true,"mis_target":"M2-1-u5-X12"},{"t":"도윤 — 「모두 19개야.」","mis":"M2-1-u5-X07"},{"t":"아린 — 「플라스틱이 종이보다 2개 더 많아.」","mis":"M2-1-u5-X11"}],"explanation":["캔은 5개로 가장 적어요.","가장 많은 것은 플라스틱이에요.","나머지 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#21','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C4',3,'mc','auto','책 13권을 색깔에 따라 나누면 빨간색 7권, 파란색 6권이에요. 같은 책을 종류에 따라 나누면 동화책이 9권이고 나머지는 모두 과학책이에요. 과학책은 몇 권일까요?',ARRAY['M2-1-u5-X07','M2-1-u5-X04']::text[],false,'{"seq":21,"concept":"M2-1-u5-C4","difficulty":3,"kind":"mc","stem":"책 13권을 색깔에 따라 나누면 빨간색 7권, 파란색 6권이에요. 같은 책을 종류에 따라 나누면 동화책이 9권이고 나머지는 모두 과학책이에요. 과학책은 몇 권일까요?","options":[{"t":"4권","correct":true},{"t":"13권","mis":"M2-1-u5-X07"},{"t":"6권","mis":"M2-1-u5-X04"}],"explanation":["기준을 바꾸어 나누어도 전체는 13권 그대로예요.","13 − 9 = 4이니 4권이에요.","각 칸의 수를 더하면 전체 수와 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#22','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C5',3,'mc','auto','교실 공을 종류에 따라 세었어요. 가장 적은 공을 하나 더 사려고 해요. 어떤 공을 사면 좋을까요?',ARRAY['M2-1-u5-X12','M2-1-u5-X10']::text[],false,'{"seq":22,"concept":"M2-1-u5-C5","difficulty":3,"kind":"mc","stem":"교실 공을 종류에 따라 세었어요. 가장 적은 공을 하나 더 사려고 해요. 어떤 공을 사면 좋을까요?","options":[{"t":"농구공","correct":true},{"t":"축구공","mis":"M2-1-u5-X12"},{"t":"배구공","mis":"M2-1-u5-X10"}],"explanation":["축구공 6개, 농구공 2개, 배구공 4개예요.","가장 적은 것은 농구공이에요.","분류한 결과로 필요한 것을 정할 수 있어요."],"asset":{"type":"sort_table","crit":"kind","cols":["축구공","농구공","배구공"],"counts":[6,2,4],"unit":"개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#23','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C2',4,'essay','teacher','친구가 「예쁜 단추와 안 예쁜 단추」로 나누자고 했어요. 이 기준의 문제점을 쓰고, 누가 나누어도 결과가 같은 기준으로 고쳐 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-1-u5-C2","difficulty":4,"kind":"essay","stem":"친구가 「예쁜 단추와 안 예쁜 단추」로 나누자고 했어요. 이 기준의 문제점을 쓰고, 누가 나누어도 결과가 같은 기준으로 고쳐 써 보세요.","answer_guide":{"answer":"예: 예쁜 단추와 안 예쁜 단추는 사람마다 생각이 달라 누가 나누느냐에 따라 결과가 달라진다. 빨간색·파란색·노란색처럼 색깔로 나누면 누가 나누어도 같다.","scoring_points":["사람마다 생각이 달라 결과가 달라진다고 썼는가","분명한 기준을 하나 골랐는가","고친 기준으로 생기는 칸을 예로 들었는가"]},"explanation":["사람마다 다른 기준은 결과가 달라요.","색깔·모양·종류·수는 누가 보아도 같아요.","분명한 기준으로 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#24','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C4',4,'essay','teacher','그림의 과일을 종류에 따라 분류하여 세는 방법을 쓰고, 센 결과를 「사과 ○개, 귤 ○개, 포도 ○개」 꼴로 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u5-C4","difficulty":4,"kind":"essay","stem":"그림의 과일을 종류에 따라 분류하여 세는 방법을 쓰고, 센 결과를 「사과 ○개, 귤 ○개, 포도 ○개」 꼴로 써 보세요.","answer_guide":{"answer":"예: 종류에 따라 칸을 정하고 하나 셀 때마다 ／ 표시를 하며 센다. 사과 3개, 귤 4개, 포도 3개. 모두 더하면 10개로 전체 수와 같다.","scoring_points":["종류에 따라 칸을 정했는가","／ 표시를 하며 빠짐없이 세는 방법을 썼는가","칸마다 수를 바르게 쓰고 합이 전체 수와 같은지 확인했는가"]},"explanation":["기준에 따라 칸을 정해요.","／ 표시를 하며 세요.","칸의 수를 더해 전체 수와 견주어요."],"asset":{"type":"sort_pile","items":["🍎","🍊","🍇","🍊","🍎","🍇","🍊","🍎","🍇","🍊"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u5_review_d#25','math',2,1,'u5','','g2_1_math_u5_review_d','unit_review','M2-1-u5-C5',4,'essay','teacher','표를 보고 알 수 있는 것을 세 가지 써 보세요. (가장 많은 것, 가장 적은 것, 전체 수, 몇 개 더 많은지 등)','{}'::text[],false,'{"seq":25,"concept":"M2-1-u5-C5","difficulty":4,"kind":"essay","stem":"표를 보고 알 수 있는 것을 세 가지 써 보세요. (가장 많은 것, 가장 적은 것, 전체 수, 몇 개 더 많은지 등)","answer_guide":{"answer":"예: 다리가 2개인 동물이 7마리로 가장 많다. 다리가 0개인 동물이 2마리로 가장 적다. 동물은 모두 13마리이다.","scoring_points":["가장 많은 것을 수와 함께 썼는가","가장 적은 것을 수와 함께 썼는가","전체 수나 두 칸의 차이를 바르게 구해 썼는가"]},"explanation":["수를 견주어 많고 적음을 찾아요.","모두 더하면 전체 수예요.","표에 있는 것만 말해요."],"asset":{"type":"sort_table","crit":"legs","cols":["다리 0개","다리 2개","다리 4개"],"counts":[2,7,4],"unit":"마리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
